import { SidebarProvider } from '@/shared/ui/sidebar';
import { AppSidebar } from './AppSidebar';
import { StoreChangeNotification } from './StoreChangeNotification';
import { useMiaGlassBoxContext } from '@/shared/contexts/MiaContext';
import { MiaFab } from '@/features/mia/ui/MiaFab';
import {
  MiaGlassBoxPane,
  MiaGlassBoxMobileSheet,
  MiaHighlightOverlay,
  MiaCursorAvatar,
  MiaErrorBoundary,
  MiaAutoProposalBanner,
  MiaActivityGlow,
  MiaStatusPill,
  MiaPageTransition,
} from '@/features/mia/ui';
import { MiaLockOverlay } from '@/features/mia/ui/MiaLockOverlay';
import { useMiaAutoDiscover } from '@/features/mia/hooks/useMiaAutoDiscover';
import { useMiaKeyboardShortcuts } from '@/features/mia/hooks/useMiaKeyboardShortcuts';
import { useMiaNavigationGraph } from '@/features/mia/hooks/useMiaNavigationGraph';
import { usePendingNfCaptureRedirect } from '@/features/notas-fiscais/model/usePendingNfCaptureRedirect';
import { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ResizableHandle, ResizablePanel, ResizablePanelGroup } from '@/shared/ui/resizable';
import { useIsMobile } from '@/shared/hooks/use-mobile';
import { useLocation } from 'react-router-dom';
import { cn } from '@/shared/lib/utils';
import { useActivityTracker } from '@/hooks/useActivityTracker';
import { usePermissions } from '@/shared/hooks/usePermissions';

interface DashboardLayoutProps {
  children: React.ReactNode;
}

/**
 * Inner — renderiza UI. Separado do Provider pra poder consumir o context.
 */
function DashboardLayoutInner({ children }: DashboardLayoutProps) {
  useActivityTracker();
  useMiaAutoDiscover();
  useMiaKeyboardShortcuts();
  useMiaNavigationGraph();
  // Se a PWA reiniciou no meio de uma captura de NF (Android matando o
  // WebView por OOM), restaura a foto pendente redirecionando pra /notas-fiscais.
  usePendingNfCaptureRedirect();
  const { canViewMia } = usePermissions();
  const navigateRouter = useNavigate();

  // MIA glass-box do_navigate listener — quando agent emite navegação,
  // react-router muda a rota e useMiaAutoDiscover roda no nova Page Model.
  useEffect(() => {
    const handler = (e: Event) => {
      const route = (e as CustomEvent<{ route: string }>).detail?.route;
      if (route && typeof route === 'string') {
        try { navigateRouter(route); } catch (err) {
          console.warn('[MIA glass-box] navigate failed:', err);
        }
      }
    };
    window.addEventListener('mia:navigate', handler);
    return () => window.removeEventListener('mia:navigate', handler);
  }, [navigateRouter]);
  // useIsMobile() agora retorna true para qualquer viewport não-desktop
  // (phone + tablet portrait + tablet landscape). Sidebar colapsa em todos.
  const isMobile = useIsMobile();
  const location = useLocation();
  const isDashboard = location.pathname === '/dashboard';
  const { miaModeEnabled, paneSize, setPaneSize } = useMiaGlassBoxContext();

  // CSS variável global pra modais respeitarem largura do MIA pane.
  // Sem isso, Dialog/Sheet centralizam em 50% do viewport e ficam atrás
  // do chat MIA. Componentes que querem centralizar na área ERP usam:
  //   left: calc((100vw - var(--mia-pane-width, 0px)) / 2)
  useEffect(() => {
    if (typeof document === 'undefined') return;
    const root = document.documentElement;
    if (miaModeEnabled && !isMobile) {
      const widthPx = `${(paneSize ?? 33) / 100}`;
      root.style.setProperty('--mia-pane-width', `calc(${widthPx} * 100vw)`);
      root.style.setProperty('--mia-erp-width', `calc((1 - ${widthPx}) * 100vw)`);
      root.setAttribute('data-mia-pane-open', 'true');
    } else {
      root.style.removeProperty('--mia-pane-width');
      root.style.removeProperty('--mia-erp-width');
      root.removeAttribute('data-mia-pane-open');
    }
  }, [miaModeEnabled, paneSize, isMobile]);

  // ── MIA pane shield contra Radix modal-mode ─────────────────────
  // Radix Dialog (mesmo com modal=false em alguns cenários transiente)
  // aplica `inert` + `aria-hidden="true"` em body siblings do portal.
  // O MIA pane fica num desses siblings → totalmente bloqueado pra clicks
  // e seleções até o modal fechar.
  //
  // Solução: MutationObserver vigia body. Quando qualquer ancestor do pane
  // recebe inert/aria-hidden, arranca imediatamente. Funciona contra
  // qualquer lib (Radix, react-aria, headless-ui) que use a mesma técnica.
  useEffect(() => {
    if (typeof document === 'undefined') return;
    if (!miaModeEnabled || isMobile) return;

    const unblockPaneAncestors = () => {
      const pane = document.querySelector('.mia-momma-surface');
      if (!pane) return;
      let node: HTMLElement | null = pane as HTMLElement;
      while (node && node !== document.body) {
        if (node.hasAttribute('inert')) {
          node.removeAttribute('inert');
        }
        if (node.getAttribute('aria-hidden') === 'true') {
          node.removeAttribute('aria-hidden');
        }
        node = node.parentElement;
      }
    };

    // Run uma vez e depois em cada mutação
    unblockPaneAncestors();
    const observer = new MutationObserver(() => unblockPaneAncestors());
    observer.observe(document.body, {
      attributes: true,
      subtree: true,
      attributeFilter: ['inert', 'aria-hidden'],
    });

    return () => observer.disconnect();
  }, [miaModeEnabled, isMobile]);

  // Pages that use p-0 (full-bleed content, no padding)
  const isFullBleedPage =
    (isMobile && isDashboard) ||
    location.pathname === '/dashboard' ||
    location.pathname.startsWith('/eventos') ||
    location.pathname.startsWith('/producao') ||
    location.pathname === '/verificacao-perdas' ||
    location.pathname === '/marketing' ||
    location.pathname === '/encomendas' ||
    location.pathname === '/produtos' ||
    location.pathname === '/produtos/analytics' ||
    location.pathname === '/notas-fiscais' ||
    location.pathname === '/financeiro' ||
    location.pathname === '/movimentacoes' ||
    location.pathname === '/pronta-entrega' ||
    location.pathname === '/producao-diaria' ||
    location.pathname === '/vendas' ||
    location.pathname === '/etiquetas' ||
    location.pathname === '/mia' ||
    location.pathname === '/logistica' ||
    location.pathname === '/logistica/control-tower' ||
    location.pathname === '/requisicao' ||
    location.pathname === '/requisicao-conclusao' ||
    location.pathname === '/atendimento-virtual' ||
    location.pathname === '/noaa-supervisor' ||
    location.pathname === '/funcionarios' ||
    location.pathname.startsWith('/funcionarios/');

  const mainContent = (
    <div className="flex-1 flex flex-col min-w-0 min-h-0 h-full">
      {/* Header removido — tudo integrado no sidebar (Todoist-style) */}
      <main
        className={cn(
          'flex-1 min-h-0 overflow-y-auto overflow-x-hidden max-w-full flex flex-col',
          (!isMobile || !isDashboard) && 'pb-[env(safe-area-inset-bottom)]',
          isFullBleedPage ? 'p-0' : 'p-3 sm:p-4 md:p-6',
        )}
      >
        {/* PageTransition envolve children: fade out/in suave entre rotas
            quando Modo IA está ON. Sem MIA, instantâneo. */}
        <MiaPageTransition>
          {children}
        </MiaPageTransition>
      </main>
      {/* Footer institucional removido */}
    </div>
  );

  // MIA 2.0 Glass-Box: split view quando Modo IA ON (desktop apenas).
  // Mobile usa bottom sheet (MiaGlassBoxMobileSheet).
  const showSplitView = miaModeEnabled && !isMobile && canViewMia();

  return (
    <SidebarProvider defaultOpen={!isMobile}>
      <StoreChangeNotification />
      {/* h-screen overflow-hidden = viewport-sized root.
          NUNCA cresce com conteúdo. Scroll move só o painel interno. */}
      <div className="h-screen overflow-hidden flex w-full bg-background">
        <AppSidebar />
        {showSplitView ? (
          <ResizablePanelGroup
            direction="horizontal"
            onLayout={(sizes) => sizes[1] && setPaneSize(Math.round(sizes[1]))}
            className="flex-1 min-w-0 h-full"
          >
            <ResizablePanel
              defaultSize={100 - paneSize}
              minSize={40}
              className="overflow-hidden"
            >
              {mainContent}
            </ResizablePanel>
            <ResizableHandle withHandle />
            <ResizablePanel
              defaultSize={paneSize}
              minSize={20}
              maxSize={60}
              className="relative z-[60] bg-background h-full"
            >
              <MiaErrorBoundary>
                <MiaGlassBoxPane />
              </MiaErrorBoundary>
            </ResizablePanel>
          </ResizablePanelGroup>
        ) : (
          mainContent
        )}
      </div>
      {canViewMia() && <MiaFab />}
      {/* MIA 2.0 Glass-Box: overlays globais — destacam elementos quando MIA atua.
          MiaStatusPill = Living Breadcrumb (unifica nav + execução + streaming
          num único pill top-center; substitui MiaNavigationToast). */}
      <MiaActivityGlow />
      <MiaStatusPill />
      <MiaHighlightOverlay />
      <MiaLockOverlay />
      <MiaCursorAvatar />
      {/* Bottom sheet mobile — só monta quando miaModeEnabled + isMobile */}
      <MiaErrorBoundary>
        <MiaGlassBoxMobileSheet />
      </MiaErrorBoundary>
      {/* Workflow auto-save é SILENCIOSO agora — sem dialog. Workflows são
          gravados em background no bridge (autoSaveWorkflow). MiaAutoProposalBanner
          mostra propostas geradas pelo pattern detector cron (3+ repetições)
          como sugestão discreta bottom-right, mas user NÃO precisa aceitar
          nada pra ações dele virarem aprendizado. */}
      {/* Auto-detected proposal banner — bottom-right pill com propostas pending */}
      <MiaErrorBoundary>
        <MiaAutoProposalBanner />
      </MiaErrorBoundary>
      {/* MiaChatPanel (chat flutuante) removido — clique no FAB agora navega
          direto pra /mia (página dedicada em "Agentes de IA"). Chat inline
          estava sendo usado sem necessidade pelos usuários. */}
    </SidebarProvider>
  );
}

/**
 * DashboardLayout — wrapper público. MiaProvider foi MOVIDO pro App.tsx
 * (acima de Routes) pra persistir state entre navegações — antes ele
 * re-montava em cada route change, fazendo chat sumir + tab resetar
 * quando MIA usava do_navigate.
 */
export function DashboardLayout({ children }: DashboardLayoutProps) {
  return <DashboardLayoutInner>{children}</DashboardLayoutInner>;
}

