import { Sparkles } from 'lucide-react';
import { useMiaGlassBoxContext } from '@/shared/contexts/MiaContext';
import { usePermissions } from '@/shared/hooks/usePermissions';
import { Button } from '@/shared/ui/button';
import { Badge } from '@/shared/ui/badge';
import { cn } from '@/shared/lib/utils';

interface MiaModeToggleProps {
  variant?: 'sidebar' | 'compact';
  className?: string;
}

/**
 * Botão "Modo IA" — ativa o glass-box pane (split view com MIA operando).
 *
 * Variants:
 * - sidebar: full-width na sidebar desktop (com label "Modo IA" + Badge ON)
 * - compact: ícone-only no header mobile (ao lado do StoreSelector)
 */
export function MiaModeToggle({ variant = 'sidebar', className }: MiaModeToggleProps) {
  const { miaModeEnabled, toggleMiaMode } = useMiaGlassBoxContext();
  const { canViewMia } = usePermissions();

  if (!canViewMia()) return null;

  if (variant === 'compact') {
    return (
      <Button
        type="button"
        variant={miaModeEnabled ? 'default' : 'outline'}
        size="icon"
        onClick={toggleMiaMode}
        aria-label={miaModeEnabled ? 'Desativar Modo IA' : 'Ativar Modo IA'}
        aria-pressed={miaModeEnabled}
        title={miaModeEnabled ? 'Modo IA ON' : 'Modo IA OFF'}
        data-mia-action="toggle-mia-mode"
        className={cn(
          'h-9 w-9 shrink-0 transition-all',
          miaModeEnabled && 'bg-gradient-to-br from-emerald-500 to-teal-600 text-white hover:from-emerald-600 hover:to-teal-700 border-transparent',
          className,
        )}
      >
        <Sparkles className={cn('h-4 w-4', miaModeEnabled && 'animate-pulse')} />
      </Button>
    );
  }

  // variant === 'sidebar'
  return (
    <Button
      type="button"
      variant="ghost"
      onClick={toggleMiaMode}
      aria-pressed={miaModeEnabled}
      data-mia-action="toggle-mia-mode"
      className={cn(
        'w-full justify-start gap-2 h-9 px-2',
        miaModeEnabled && 'bg-emerald-500/10 text-emerald-700 dark:text-emerald-300 hover:bg-emerald-500/15',
        className,
      )}
    >
      <Sparkles className={cn('h-4 w-4', miaModeEnabled && 'animate-pulse')} />
      <span className="text-sm">Modo IA</span>
      {miaModeEnabled ? (
        <Badge variant="secondary" className="ml-auto text-[10px] px-1.5 py-0">
          ON
        </Badge>
      ) : (
        <span className="ml-auto text-[10px] text-muted-foreground">desligado</span>
      )}
    </Button>
  );
}

