function DashboardLayoutInner({ children }: DashboardLayoutProps) {
  useActivityTracker();
  useMiaAutoDiscover();
  useMiaKeyboardShortcuts();
  useMiaNavigationGraph();
  // Se a PWA reiniciou no meio de uma captura de NF (Android matando o
  // WebView por OOM), restaura a foto pendente redirecionando pra /notas-fiscais.
  usePendingNfCaptureRedirect();
  const { canViewMia } = usePermissions();
  const navigateRouter = useNavigate();

  // MIA glass-box do_navigate listener — quando agent emite navegação,
  // react-router muda a rota e useMiaAutoDiscover roda no nova Page Model.
  useEffect(() => {
    const handler = (e: Event) => {
      const route = (e as CustomEvent<{ route: string }>).detail?.route;
      if (route && typeof route === 'string') {
        try { navigateRouter(route); } catch (err) {
          console.warn('[MIA glass-box] navigate failed:', err);
        }
      }
    };
    window.addEventListener('mia:navigate', handler);
    return () => window.removeEventListener('mia:navigate', handler);
  }, [navigateRouter]);
  // useIsMobile() agora retorna true para qualquer viewport não-desktop
  // (phone + tablet portrait + tablet landscape). Sidebar colapsa em todos.
  const isMobile = useIsMobile();
  const location = useLocation();
  const isDashboard = location.pathname === '/dashboard';
  const { miaModeEnabled, paneSize, setPaneSize } = useMiaGlassBoxContext();

  // CSS variável global pra modais respeitarem largura do MIA pane.
  // Sem isso, Dialog/Sheet centralizam em 50% do viewport e ficam atrás
  // do chat MIA. Componentes que querem centralizar na área ERP usam:
  //   left: calc((100vw - var(--mia-pane-width, 0px)) / 2)
  useEffect(() => {
    if (typeof document === 'undefined') return;
    const root = document.documentElement;
    if (miaModeEnabled && !isMobile) {
      const widthPx = `${(paneSize ?? 33) / 100}`;
      root.style.setProperty('--mia-pane-width', `calc(${widthPx} * 100vw)`);
      root.style.setProperty('--mia-erp-width', `calc((1 - ${widthPx}) * 100vw)`);
      root.setAttribute('data-mia-pane-open', 'true');
    } else {
      root.style.removeProperty('--mia-pane-width');
      root.style.removeProperty('--mia-erp-width');
      root.removeAttribute('data-mia-pane-open');
    }
  }, [miaModeEnabled, paneSize, isMobile]);

  // ── MIA pane shield contra Radix modal-mode ─────────────────────
  // Radix Dialog (mesmo com modal=false em alguns cenários transiente)
  // aplica `inert` + `aria-hidden="true"` em body siblings do portal.
  // O MIA pane fica num desses siblings → totalmente bloqueado pra clicks
  // e seleções até o modal fechar.
  //
  // Solução: MutationObserver vigia body. Quando qualquer ancestor do pane
  // recebe inert/aria-hidden, arranca imediatamente. Funciona contra
  // qualquer lib (Radix, react-aria, headless-ui) que use a mesma técnica.
  useEffect(() => {
    if (typeof document === 'undefined') return;
    if (!miaModeEnabled || isMobile) return;

    const unblockPaneAncestors = () => {
      const pane = document.querySelector('.mia-momma-surface');
      if (!pane) return;
      let node: HTMLElement | null = pane as HTMLElement;
      while (node && node !== document.body) {
        if (node.hasAttribute('inert')) {
          node.removeAttribute('inert');
        }
        if (node.getAttribute('aria-hidden') === 'true') {
          node.removeAttribute('aria-hidden');
        }
        node = node.parentElement;
      }
    };

    // Run uma vez e depois em cada mutação
    unblockPaneAncestors();
    const observer = new MutationObserver(() => unblockPaneAncestors());
    observer.observe(document.body, {
      attributes: true,
      subtree: true,
      attributeFilter: ['inert', 'aria-hidden'],
    });

    return () => observer.disconnect();
  }, [miaModeEnabled, isMobile]);

  // Pages that use p-0 (full-bleed content, no padding)

