// MIA 2.0 Glass-Box — Phase 11 wire-up.
// Glass-box agent (reasoning model + plan dinâmico + DOM sequence) é
// ATIVADO POR DEFAULT quando glass-box mode ON. Pra desabilitar
// explicitamente, setar MIA_GLASS_BOX_AGENT_ENABLED=false/0/off.
// Se glass-box mode OFF, comportamento MIA 1.x preservado normalmente.
const MIA_GLASS_BOX_AGENT_ENABLED = (() => {
    const v = (Deno.env.get('MIA_GLASS_BOX_AGENT_ENABLED') ?? '').toLowerCase().trim()
    if (v === '0' || v === 'false' || v === 'off' || v === 'no') return false
    return true // default ON
})()

