const OPENROUTER_API_KEY = Deno.env.get('OPENROUTER_API_KEY')

// ── Query Cache (TTL 60s) — evita re-queries idênticas em conversas com repetição ──
const _queryCache = new Map<string, { data: string; ts: number }>()
const CACHE_TTL = 60_000 // 1 minuto

export function getCachedToolResult(toolName: string, args: any): string | null {
    const key = `${toolName}:${JSON.stringify(args)}`
    const cached = _queryCache.get(key)
    if (cached && Date.now() - cached.ts < CACHE_TTL) {
        console.log(`[CACHE HIT] ${toolName} (${Math.round((Date.now() - cached.ts) / 1000)}s old)`)
        return cached.data
    }
    return null
}

export function setCachedToolResult(toolName: string, args: any, data: string): void {
    const key = `${toolName}:${JSON.stringify(args)}`
    _queryCache.set(key, { data, ts: Date.now() })
    // Evitar memory leak: limpar entries > 5min
    if (_queryCache.size > 100) {
        const now = Date.now()
        for (const [k, v] of _queryCache) {
            if (now - v.ts > 300_000) _queryCache.delete(k)
        }
    }
}

// ── Token Estimator — rough heuristic para context window management ──
export function estimateTokens(text: string): number {
    // Heurística: ~4 chars por token em português (testado empiricamente)
    return Math.ceil((text || '').length / 4)
}

export function estimateMessagesTokens(messages: any[]): number {
    return messages.reduce((sum, m) => {
        const content = typeof m.content === 'string' ? m.content : JSON.stringify(m.content || '')
        return sum + estimateTokens(content) + 4 // +4 per message overhead
    }, 0)
}

// Default primary: openai/gpt-4.1-mini — escolhido após evidência empírica de
// falha do grok-4.1-fast em tool calling (3 testes consecutivos retornando
// tools_called=[] mesmo com tool_choice='required'). OpenAI tunada
// religiosamente pra function calling + tool_choice. Custo ~2x Grok mas
// ROI alto pelo que cobre. Anthropic Haiku como secondary (gold standard
// se primary rate-limit). Gemini Flash como terciário (fallback rápido).
// Grok mantido como quaternário só pra fluxos GENERAL sem tools.
export const PRIMARY_MODEL = "openai/gpt-4.1-mini"
const FALLBACK_CHAIN = [
    "openai/gpt-4.1-mini",
    "anthropic/claude-haiku-4.5",
    "google/gemini-2.5-flash",
    "x-ai/grok-4.1-fast",
]

// MIA 2.0 Glass-Box (Phase 9) — Reasoning tier.
// Pra etapas que beneficiam de raciocínio profundo: plan generation no
// glass-box mode, distillation do Mirror (background), specialist analysis,
// reflection step (auto-critique), ambiguity detection (Ask vs Assume).
//
// 2026-05-21 (revisão pós-telemetria real):
//
// 1 modelo só (Haiku 4.5), LOW effort. Single-agent ReAct.
//
// Por quê LOW effort (era HIGH)?
//   - Telemetria real: HIGH effort = 51-90s só pra gerar plano (Round 2 da
//     NF manual mediu 51s antes do timeout). World-class (Browser-use,
//     Claude Computer Use, Nova Act SDK, OpenAI Operator) usam tactical
//     reasoning (low/none) — NINGUÉM usa high effort pra agentic execution.
//   - Schema-guided JSON output já garante estrutura — Haiku low effort
//     (~800-1500 thinking tokens) decide próxima ação rápido (10-15s).
//   - HIGH effort é pra problemas multi-hop (matemática, prova) — não pra
//     "qual o próximo botão clicar" que é decisão tactical.
//   - Decisão CTO 2026-05-21: foco em velocidade COM qualidade.
//
// Por quê não 2 modelos (planner+executor)?
//   - Benchmark AkitaOnRails 2026: "mixing planner + cheap executor LOSES to
//     just using single frontier model alone in mature harness"
//   - Multi-agent "doubles wall time + triples total cost"
//
// Por quê Haiku 4.5?
//   - Anthropic otimizou pra computer-use/agentic
//   - Zero tool-calling failures (Kilo benchmark Mini Models Battle)
//   - 50% mais barato ($1/$5 vs $2/$8)
//   - 200K context é suficiente (prompt da MIA ~30K)
export const REASONING_MODEL = "anthropic/claude-haiku-4.5"
const REASONING_FALLBACK_CHAIN = [
    "anthropic/claude-haiku-4.5",
    "anthropic/claude-sonnet-4-5",    // premium se Haiku rate-limit
    "openai/gpt-4.1",                  // OpenAI como terciário
    "google/gemini-2.5-pro",           // último recurso
]
export const REASONING_EFFORT_LEVEL: 'low' | 'medium' | 'high' = 'low'

// Per-call timeout no fetch ao OpenRouter (padrão Claude Chrome / Cursor /
// Browser-use). Sem isso, request pendurado segura o agent loop até o
// Supabase Edge Function matar tudo (~150s) e o user vê "external_timeout em
// loops". Com timeout per-call, fallback chain atua rápido: Haiku 35s →
// Sonnet 35s → GPT 35s → Gemini 35s, ao invés de 1 modelo pendurado.
//
// 35s pra reasoning (LLM tactical pode demorar). 25s pra calls regulares.
const LLM_FETCH_TIMEOUT_MS = 25_000
const REASONING_FETCH_TIMEOUT_MS = 35_000

/** Cria AbortSignal que aborta após `ms`. Polyfill pra runtimes antigos. */
function timeoutSignal(ms: number): AbortSignal {
    // Deno >=1.36 tem AbortSignal.timeout nativo
    if (typeof (AbortSignal as any).timeout === 'function') {
        return (AbortSignal as any).timeout(ms)
    }
    const ac = new AbortController()
    setTimeout(() => ac.abort(new DOMException('Request timed out', 'TimeoutError')), ms)
    return ac.signal
}

// Marca um breakpoint de cache no último bloco estático. Grok via OpenRouter
// faz cache automático por prefixo (não usa o campo). Anthropic-like providers
// leem cache_control ephemeral. Passar em ambos = universal.
export function withCacheBreakpoint(text: string): any {
    return [{ type: "text", text, cache_control: { type: "ephemeral" } }]
}

/**
 * Monta system messages separando prefixo estático (cacheável) de contexto
 * dinâmico (varia por turno). Estável primeiro, dinâmico no fim — prefix
 * cache do provider preserva os tokens do estável entre requests.
 */
export function buildSystemMessages(staticPrompt: string, dynamicContext?: string | null): any[] {
    const messages: any[] = [
        { role: 'system', content: withCacheBreakpoint(staticPrompt) }
    ]
    if (dynamicContext && dynamicContext.trim()) {
        messages.push({ role: 'system', content: `<current_context>\n${dynamicContext}\n</current_context>` })
    }
    return messages
}

export async function callLLM(
    messages: any[],
    tools: any[] = [],
    model: string = PRIMARY_MODEL,
    temperature: number = 0,
    toolChoice?: 'auto' | 'required' | 'none' | { type: 'function'; function: { name: string } },
    forceJson: boolean = false,
): Promise<any> {
    if (!OPENROUTER_API_KEY) throw new Error("Missing OPENROUTER_API_KEY")

    // Build ordered model list: requested model first, then fallbacks (deduped)
    const models = [model, ...FALLBACK_CHAIN.filter(m => m !== model)]

    for (let i = 0; i < models.length; i++) {
        const currentModel = models[i]
        try {
            console.log(`[LLM] Calling ${currentModel}${i > 0 ? ` (fallback #${i})` : ''} with ${messages.length} messages${toolChoice ? `, tool_choice=${typeof toolChoice === 'string' ? toolChoice : 'specific'}` : ''}${forceJson ? ' json_object' : ''}...`)

            const body: any = {
                model: currentModel,
                messages: messages,
                temperature: temperature,
                // Reasoning low quando há tools (escolha de tool é mecânica), high
                // só pra resposta sem tools (raciocínio sobre dados na própria resposta).
                reasoning: { effort: tools.length > 0 ? "low" : "high" },
                // Tabelas longas (lista de mês inteiro) podem chegar a 30K chars.
                // Reasoning + tabela precisa de bastante budget.
                max_tokens: 32000,
            }
            // forceJson: força modelo a retornar JSON puro.
            // Sem isso, Haiku às vezes responde texto livre que quebra JSON.parse.
            if (forceJson) {
                body.response_format = { type: 'json_object' }
            }

            if (tools.length > 0) {
                body.tools = tools.map(t => ({ type: "function", function: t }))
                // tool_choice: 'required' força o modelo a chamar UMA tool (não responder texto).
                // Anthropic/OpenAI/Grok via OpenRouter respeitam isso. Usado pelo critic guardrail
                // pra evitar Grok pular tools em queries factuais.
                if (toolChoice) {
                    body.tool_choice = toolChoice
                }
            }

            let response: Response
            try {
                response = await fetch("https://openrouter.ai/api/v1/chat/completions", {
                    method: "POST",
                    headers: {
                        "Authorization": `Bearer ${OPENROUTER_API_KEY}`,
                        "Content-Type": "application/json",
                        "HTTP-Referer": "https://momma.app",
                        "X-Title": "Momma Stock Insight"
                    },
                    body: JSON.stringify(body),
                    signal: timeoutSignal(LLM_FETCH_TIMEOUT_MS),
                })
            } catch (fetchErr) {
                const isTimeout = (fetchErr as any)?.name === 'TimeoutError'
                    || (fetchErr as any)?.name === 'AbortError'
                console.error(`[LLM] ${currentModel} ${isTimeout ? `TIMEOUT (${LLM_FETCH_TIMEOUT_MS}ms)` : 'fetch error'}:`, fetchErr)
                if (i === models.length - 1) throw fetchErr
                continue
            }

            if (!response.ok) {
                const errText = await response.text()
                console.error(`[LLM] ${currentModel} failed (${response.status}): ${errText.substring(0, 200)}`)
                // On 429 (rate limit) or 5xx, try next model
                if (response.status === 429 || response.status >= 500) continue
                // On 4xx (bad request, auth), also try fallback — model might not exist
                if (response.status >= 400) continue
                throw new Error(`LLM API Error (${response.status}): ${errText}`)
            }

            const data = await response.json()

            if (!data.choices?.[0]?.message) {
                console.error(`[LLM] ${currentModel} returned empty response`)
                continue
            }

            // Cache telemetry: OpenRouter devolve cached_tokens em prompt_tokens_details
            const cached = data.usage?.prompt_tokens_details?.cached_tokens ?? 0
            const prompt = data.usage?.prompt_tokens ?? 0
            if (prompt > 0) {
                const hitRate = cached > 0 ? Math.round((cached / prompt) * 100) : 0
                console.log(`[LLM] ${currentModel} tokens: prompt=${prompt} cached=${cached} (${hitRate}%) completion=${data.usage?.completion_tokens ?? 0}`)
            }
            if (i > 0) console.log(`[LLM] Succeeded with fallback: ${currentModel}`)
            return data.choices[0].message

        } catch (err) {
            console.error(`[LLM] ${currentModel} exception: ${err}`)
            if (i === models.length - 1) throw err
        }
    }

    throw new Error(`All LLM models failed: ${models.join(', ')}`)
}

// ============================================================================
// MIA 2.0 Glass-Box (Phase 9) — Reasoning LLM helper
//
// Usa Claude Haiku 4.5 (Anthropic, 2026-05-20) com reasoning.effort=high
// pra plan generation, distillation, specialist analysis, ambiguity detection.
// Fallback chain: Haiku 4.5 → Sonnet 4.5 → GPT-4.1 → Gemini Pro.
// OpenRouter normaliza reasoning.effort para a API nativa de cada provider
// (Anthropic usa "thinking", OpenAI usa "reasoning", Gemini "thinkingConfig").
// ============================================================================

export async function callReasoningLLM(
    messages: any[],
    tools: any[] = [],
    temperature: number = 0,
    toolChoice?: 'auto' | 'required' | 'none' | { type: 'function'; function: { name: string } },
    forceJson: boolean = false,
): Promise<any> {
    if (!OPENROUTER_API_KEY) throw new Error("Missing OPENROUTER_API_KEY")

    const models = REASONING_FALLBACK_CHAIN.slice()

    for (let i = 0; i < models.length; i++) {
        const currentModel = models[i]
        try {
            console.log(`[LLM-REASONING] Calling ${currentModel}${i > 0 ? ` (fallback #${i})` : ''} effort=${REASONING_EFFORT_LEVEL}${forceJson ? ' json_object' : ''}`)

            const body: any = {
                model: currentModel,
                messages: messages,
                temperature: temperature,
                // Reasoning effort LOW (era high). Telemetria real mostrou
                // 51s/round em high — incompatível com glass-box tactical.
                // Low = 5-15s, schema-guided JSON mantém qualidade.
                reasoning: { effort: REASONING_EFFORT_LEVEL },
                max_tokens: 32000,
            }
            // forceJson: força modelo a retornar JSON puro (sem prose depois).
            // Haiku 4.5 low effort às vezes adiciona explicação depois do
            // JSON — quebra JSON.parse. response_format=json_object resolve
            // (Anthropic + OpenAI + Gemini via OpenRouter respeitam).
            if (forceJson) {
                body.response_format = { type: 'json_object' }
            }

            if (tools.length > 0) {
                body.tools = tools.map(t => ({ type: "function", function: t }))
                if (toolChoice) {
                    body.tool_choice = toolChoice
                }
            }

            let response: Response
            try {
                response = await fetch("https://openrouter.ai/api/v1/chat/completions", {
                    method: "POST",
                    headers: {
                        "Authorization": `Bearer ${OPENROUTER_API_KEY}`,
                        "Content-Type": "application/json",
                        "HTTP-Referer": "https://momma-stock-insight.lovable.app",
                        "X-Title": "Momma Stock Insight (MIA Reasoning)",
                    },
                    body: JSON.stringify(body),
                    signal: timeoutSignal(REASONING_FETCH_TIMEOUT_MS),
                })
            } catch (fetchErr) {
                const isTimeout = (fetchErr as any)?.name === 'TimeoutError'
                    || (fetchErr as any)?.name === 'AbortError'
                console.warn(`[LLM-REASONING] ${currentModel} ${isTimeout ? `TIMEOUT (${REASONING_FETCH_TIMEOUT_MS}ms)` : 'fetch error'}:`, fetchErr)
                if (i < models.length - 1) continue
                throw fetchErr
            }

            if (!response.ok) {
                const errText = await response.text()
                console.warn(`[LLM-REASONING] ${currentModel} failed: ${response.status} ${errText.slice(0, 200)}`)
                if (i < models.length - 1) continue
                throw new Error(`Reasoning LLM ${currentModel} failed: ${response.status}`)
            }

            const data = await response.json()
            // Log do modelo que REALMENTE respondeu (OpenRouter pode rotear)
            const respModel = data?.model ?? data?.id ?? currentModel
            const usage = data?.usage
            console.log(`[LLM-REASONING] ✓ ${respModel} respondeu (asked=${currentModel}, ${usage ? `${usage.prompt_tokens}+${usage.completion_tokens} tok` : 'no-usage'})`)
            return data
        } catch (err) {
            console.warn(`[LLM-REASONING] ${currentModel} error:`, err)
            if (i < models.length - 1) continue
            throw err
        }
    }

    throw new Error(`All reasoning models failed: ${models.join(', ')}`)
}

// ============================================================================
// TOKEN-LEVEL STREAMING — Calls OpenRouter with stream:true and yields tokens
//
// OpenRouter SSE format:
//   data: {"choices":[{"delta":{"content":"token"}}]}\n\n
//   ": OPENROUTER PROCESSING"  (keepalive comment, skip)
//   data: [DONE]               (end of stream)
// ============================================================================

// ============================================================================
// RAW CHAT STREAMING — No system prompt, optional web search + reasoning
// Returns typed events: { type: 'token'|'reasoning', content: string }
// ============================================================================

export interface RawStreamOptions {
    webSearch?: boolean;
    reasoning?: boolean;
}

export async function* callLLMStreamRaw(
    messages: any[],
    model: string = PRIMARY_MODEL,
    temperature: number = 0.7,
    options: RawStreamOptions = {}
): AsyncGenerator<{ type: 'token' | 'reasoning'; content: string }, void, unknown> {
    if (!OPENROUTER_API_KEY) throw new Error("Missing OPENROUTER_API_KEY")

    const models = [model, ...FALLBACK_CHAIN.filter(m => m !== model)]

    for (let i = 0; i < models.length; i++) {
        const currentModel = models[i]
        try {
            console.log(`[LLM-RAW] Calling ${currentModel}${i > 0 ? ` (fallback #${i})` : ''} web_search=${!!options.webSearch} reasoning=${!!options.reasoning}`)

            const body: any = {
                model: currentModel,
                messages,
                temperature,
                stream: true,
            }

            if (options.webSearch) {
                body.plugins = [{ id: "web", engine: "native", max_results: 5 }]
            }

            if (options.reasoning) {
                body.reasoning = { effort: "high" }
            }

            const response = await fetch("https://openrouter.ai/api/v1/chat/completions", {
                method: "POST",
                headers: {
                    "Authorization": `Bearer ${OPENROUTER_API_KEY}`,
                    "Content-Type": "application/json",
                    "HTTP-Referer": "https://momma.app",
                    "X-Title": "Momma Stock Insight"
                },
                body: JSON.stringify(body)
            })

            if (!response.ok) {
                const errText = await response.text()
                console.error(`[LLM-RAW] ${currentModel} HTTP ${response.status}: ${errText.substring(0, 300)}`)
                if (response.status === 429 || response.status >= 500) continue
                if (response.status >= 400) continue
                throw new Error(`LLM Raw Error (${response.status}): ${errText}`)
            }

            const contentType = response.headers.get('content-type') || ''

            // JSON fallback
            if (contentType.includes('application/json')) {
                const data = await response.json()
                const text = data.choices?.[0]?.message?.content
                if (text) { yield { type: 'token', content: text }; return }
                continue
            }

            if (!response.body) { console.error(`[LLM-RAW] ${currentModel} no body`); continue }

            const reader = response.body.getReader()
            const decoder = new TextDecoder()
            let buffer = ''
            let tokenCount = 0
            let isDone = false

            while (!isDone) {
                const { done, value } = await reader.read()
                if (done) break

                buffer += decoder.decode(value, { stream: true })
                const parts = buffer.split('\n\n')
                buffer = parts.pop() || ''

                for (const part of parts) {
                    const lines = part.split('\n')
                    for (const line of lines) {
                        const trimmed = line.trim()
                        if (!trimmed || trimmed.startsWith(':')) continue
                        if (!trimmed.startsWith('data: ')) continue
                        const payload = trimmed.slice(6).trim()
                        if (payload === '[DONE]') { isDone = true; break }

                        try {
                            const parsed = JSON.parse(payload)
                            const delta = parsed.choices?.[0]?.delta

                            // Reasoning tokens (comes before content)
                            const reasoningDetails = delta?.reasoning_details
                            if (reasoningDetails?.length) {
                                for (const detail of reasoningDetails) {
                                    if (detail.type === 'reasoning.text' && detail.text) {
                                        yield { type: 'reasoning', content: detail.text }
                                    }
                                }
                            }

                            // Content tokens
                            if (delta?.content) {
                                tokenCount++
                                yield { type: 'token', content: delta.content }
                            }
                        } catch {}
                    }
                    if (isDone) break
                }
            }

            // Flush remaining buffer
            if (buffer.trim()) {
                const lines = buffer.split('\n')
                for (const line of lines) {
                    const trimmed = line.trim()
                    if (!trimmed.startsWith('data: ')) continue
                    const payload = trimmed.slice(6).trim()
                    if (payload === '[DONE]') break
                    try {
                        const parsed = JSON.parse(payload)
                        const delta = parsed.choices?.[0]?.delta
                        if (delta?.reasoning_details?.length) {
                            for (const d of delta.reasoning_details) {
                                if (d.type === 'reasoning.text' && d.text) yield { type: 'reasoning', content: d.text }
                            }
                        }
                        if (delta?.content) { tokenCount++; yield { type: 'token', content: delta.content } }
                    } catch {}
                }
            }

            console.log(`[LLM-RAW] ${currentModel} streamed ${tokenCount} tokens`)
            if (tokenCount > 0) return
            continue

        } catch (err) {
            console.error(`[LLM-RAW] ${currentModel} exception: ${err}`)
            if (i === models.length - 1) throw err
        }
    }

    throw new Error(`All LLM raw models failed: ${models.join(', ')}`)
}

export async function* callLLMStream(
    messages: any[],
    model: string = PRIMARY_MODEL,
    temperature: number = 0
): AsyncGenerator<string, void, unknown> {
    if (!OPENROUTER_API_KEY) throw new Error("Missing OPENROUTER_API_KEY")

    const models = [model, ...FALLBACK_CHAIN.filter(m => m !== model)]

    for (let i = 0; i < models.length; i++) {
        const currentModel = models[i]
        try {
            console.log(`[LLM-STREAM] Calling ${currentModel}${i > 0 ? ` (fallback #${i})` : ''} with stream:true...`)

            const body: any = {
                model: currentModel,
                messages: messages,
                temperature: temperature,
                stream: true,
            }

            const response = await fetch("https://openrouter.ai/api/v1/chat/completions", {
                method: "POST",
                headers: {
                    "Authorization": `Bearer ${OPENROUTER_API_KEY}`,
                    "Content-Type": "application/json",
                    "HTTP-Referer": "https://momma.app",
                    "X-Title": "Momma Stock Insight"
                },
                body: JSON.stringify(body)
            })

            if (!response.ok) {
                const errText = await response.text()
                console.error(`[LLM-STREAM] ${currentModel} HTTP ${response.status}: ${errText.substring(0, 300)}`)
                if (response.status === 429 || response.status >= 500) continue
                if (response.status >= 400) continue
                throw new Error(`LLM Stream Error (${response.status}): ${errText}`)
            }

            const contentType = response.headers.get('content-type') || ''
            console.log(`[LLM-STREAM] ${currentModel} response content-type: ${contentType}`)

            // If server returned JSON instead of SSE (some models/providers do this),
            // extract content and yield as single token
            if (contentType.includes('application/json')) {
                console.warn(`[LLM-STREAM] ${currentModel} returned JSON instead of SSE, extracting content`)
                const data = await response.json()
                const text = data.choices?.[0]?.message?.content
                if (text) {
                    yield text
                    return
                }
                console.error(`[LLM-STREAM] ${currentModel} JSON response had no content`)
                continue
            }

            if (!response.body) {
                console.error(`[LLM-STREAM] ${currentModel} no response body`)
                continue
            }

            // Read SSE stream
            const reader = response.body.getReader()
            const decoder = new TextDecoder()
            let buffer = ''
            let tokenCount = 0
            let isDone = false

            while (!isDone) {
                const { done, value } = await reader.read()
                if (done) break

                buffer += decoder.decode(value, { stream: true })

                // SSE events are separated by \n\n
                // Split on \n\n to get complete events
                const parts = buffer.split('\n\n')
                buffer = parts.pop() || '' // Keep incomplete last part

                for (const part of parts) {
                    // Each part can have multiple lines
                    const lines = part.split('\n')
                    for (const line of lines) {
                        const trimmed = line.trim()

                        // Skip empty lines and SSE comments (keepalives like ": OPENROUTER PROCESSING")
                        if (!trimmed || trimmed.startsWith(':')) continue

                        if (!trimmed.startsWith('data: ')) continue
                        const payload = trimmed.slice(6).trim()

                        if (payload === '[DONE]') {
                            isDone = true
                            break
                        }

                        try {
                            const parsed = JSON.parse(payload)
                            const content = parsed.choices?.[0]?.delta?.content
                            if (content) {
                                tokenCount++
                                yield content
                            }
                        } catch (parseErr) {
                            // Some chunks might be malformed, skip
                            if (payload.length > 0 && payload !== '[DONE]') {
                                console.warn(`[LLM-STREAM] Unparseable SSE chunk: ${payload.substring(0, 100)}`)
                            }
                        }
                    }
                    if (isDone) break
                }
            }

            // Process any remaining buffer
            if (buffer.trim()) {
                const lines = buffer.split('\n')
                for (const line of lines) {
                    const trimmed = line.trim()
                    if (!trimmed.startsWith('data: ')) continue
                    const payload = trimmed.slice(6).trim()
                    if (payload === '[DONE]') break
                    try {
                        const parsed = JSON.parse(payload)
                        const content = parsed.choices?.[0]?.delta?.content
                        if (content) {
                            tokenCount++
                            yield content
                        }
                    } catch {}
                }
            }

            console.log(`[LLM-STREAM] ${currentModel} streamed ${tokenCount} tokens`)

            if (tokenCount > 0) {
                if (i > 0) console.log(`[LLM-STREAM] Succeeded with fallback: ${currentModel}`)
                return // Successfully streamed
            }

            console.error(`[LLM-STREAM] ${currentModel} yielded 0 tokens from SSE stream`)
            continue

        } catch (err) {
            console.error(`[LLM-STREAM] ${currentModel} exception: ${err}`)
            if (i === models.length - 1) throw err
        }
    }

    throw new Error(`All LLM stream models failed: ${models.join(', ')}`)
}

