// ============================================================================
// MESSAGE ROUTER — Context-Aware Intent Classification
//
// Domains: STOCK, CATALOG, LOGISTICS, FINANCE, GENERAL
// Enhancement: Page context biases routing when user is on a specific module
// ============================================================================

function buildRouterPrompt(pageContext?: any): string {
    const currentRoute = pageContext?.route || ''
    const currentTab = pageContext?.tab || pageContext?.screen_state?.active_tab || ''

    let contextHint = ''
    if (currentRoute.includes('financeiro')) {
        contextHint = `
CONTEXT: The user is currently viewing the FINANCIAL module (page: ${currentRoute}, tab: ${currentTab}).
Questions about data on screen, values, comparisons, KPIs, or anything related to what they're looking at should be routed to FINANCE.
When ambiguous and user is on /financeiro, prefer FINANCE.`
    } else if (currentRoute.includes('notas-fiscais')) {
        contextHint = `
CONTEXT: The user is currently viewing NOTAS FISCAIS (invoices) page.
Questions about invoices, suppliers, invoice items, OCR, NF values → FINANCE.
When ambiguous and user is on /notas-fiscais, prefer FINANCE.`
    } else if (currentRoute.includes('consultar-ncm')) {
        contextHint = `
CONTEXT: The user is currently viewing the NCM lookup page.
Questions about NCM codes, fiscal classification → CATALOG.
When ambiguous, prefer CATALOG.`
    } else if (currentRoute.includes('producao-diaria')) {
        contextHint = `
CONTEXT: The user is currently viewing the DAILY PRODUCTION page (/producao-diaria).
Questions about daily production entries, registering production quantities, WhatsApp import, production history and analytics → STOCK.
When ambiguous and user is on /producao-diaria, prefer STOCK.`
    } else if (currentRoute.includes('producao/analytics')) {
        contextHint = `
CONTEXT: The user is currently viewing PRODUCTION ANALYTICS page (/producao/analytics).
This is a read-only dashboard showing OPs, fichas técnicas, insumos KPIs → STOCK.
When ambiguous, prefer STOCK.`
    } else if (currentRoute.includes('producao')) {
        contextHint = `
CONTEXT: The user is currently viewing PRODUCTION pages (${currentRoute}).
Questions about recipes, fichas técnicas, insumos, ordens de produção, rendimento → STOCK.
When ambiguous and user is on /producao, prefer STOCK.`
    } else if (currentRoute.includes('pronta-entrega')) {
        contextHint = `
CONTEXT: The user is currently viewing the PRONTA ENTREGA (ready stock board) page.
Questions about câmara fria, refrigeração, expositor, product locations → STOCK.
When ambiguous, prefer STOCK.`
    } else if (currentRoute.includes('estoque') || currentRoute.includes('visualizacao-estoque') || currentRoute.includes('movimentacoes')) {
        contextHint = `
CONTEXT: The user is currently viewing STOCK/INVENTORY pages (${currentRoute}).
When ambiguous and user is on this page, prefer STOCK.`
    } else if (currentRoute.includes('verificacao-perdas')) {
        contextHint = `
CONTEXT: The user is currently viewing the LOSS VERIFICATION page.
Questions about losses, waste, verificação de perdas → STOCK.
When ambiguous, prefer STOCK.`
    } else if (currentRoute.includes('logistica') || currentRoute.includes('requisicao')) {
        contextHint = `
CONTEXT: The user is currently viewing LOGISTICS page (${currentRoute}).
When ambiguous and user is on this page, prefer LOGISTICS.`
    } else if (currentRoute.includes('eventos') || currentRoute.includes('encomendas')) {
        contextHint = `
CONTEXT: The user is currently viewing EVENTS/ORDERS page (${currentRoute}).
Questions about events, encomendas, deliveries → LOGISTICS.
When ambiguous, prefer LOGISTICS.`
    } else if (currentRoute.includes('vendas')) {
        contextHint = `
CONTEXT: The user is currently viewing the SALES ANALYSIS page (/vendas).
Questions about sales history, demand forecasting, product performance, production suggestions → STOCK.
When ambiguous and user is on /vendas, prefer STOCK.`
    } else if (currentRoute.includes('produtos') || currentRoute.includes('product-analytics')) {
        contextHint = `
CONTEXT: The user is currently viewing PRODUCTS page (${currentRoute}).
When ambiguous, prefer CATALOG.`
    }

    return `You are the **Router** for Momma's AI Assistant (Mia).
Your job is to classify the user's intent into one of the following domains:

- **STOCK**: Questions about internal inventory (estoque), quantity, storage, expiration (validade), production (produção diária), recipes (fichas técnicas), ingredients (insumos), production orders (ordens de produção), yield (rendimento), losses (perdas/quebras), and sales history/consumption. Keywords: "quanto tem", "estoque", "câmara fria", "geladeira", "vence", "produzi", "perdi", "estragou", "vendas", "consumo", "quanto vendeu", "perda", "verificação", "ficha técnica", "receita", "insumo", "ordem de produção", "OP", "rendimento", "produção".

- **CATALOG**: Questions about product details, categories, sectors, prices, NCMs, or product configuration. Also CREATION, DEACTIVATION and VISIBILITY of products (which stores show the product). Keywords: "preço", "custo", "setor", "categoria", "código", "lista de produtos", "NCM", "código NCM", "classificação fiscal", "produto master", "criar produto", "cadastrar produto", "adicionar produto", "novo produto", "desativar produto", "remover do catálogo", "visibilidade", "aparece em quais lojas", "mostrar só", "ocultar da".

- **LOGISTICS**: Questions about custom orders (encomendas), events (eventos), requisições de produto (separação e envio de itens pedidos pelas lojas), delivery/pickup schedules, picking lists, event budgets. Keywords: "pedido", "encomenda", "cliente", "festa", "casamento", "requisição", "separação", "picking", "orçamento", "evento", "entrega".

- **FINANCE**: Questions about finances, money, billing, accounts payable/receivable (contas a pagar/receber), revenue, expenses, invoices (notas fiscais), invoice items/products, cash flow (caixa/cofre), DRE, bank reconciliation, credit cards, financial comparisons, overdue accounts, budget, categories, batch operations on financial records, undoing batch operations, session rollback, NOTAS DE TRANSFERÊNCIA (DANFEs fiscais de mercadoria entre lojas), transferências de cofre (dinheiro entre lojas), transferências bancárias, SALÁRIOS e gastos com pessoal (salário de alguém, folha, FGTS, VT, VR, CLT, PJ, freelancer). Keywords: "receita", "despesa", "faturamento", "quanto gastamos", "quanto devemos", "atrasado", "vencido", "pagar", "receber", "nota fiscal", "nota de transferência", "DANFE", "transferência", "transferimos", "comprei", "caixa", "cofre", "DRE", "banco", "cartão", "parcela", "conciliação", "morango", "fornecedor", "quanto pagamos", "categorizar em lote", "atualizar todas", "desfazer operação", "desfazer", "rollback", "undo", "desfazer tudo", "volta tudo", "reverter", "desfaz tudo que fizemos", "rollback sessão", "desfazer as últimas", "salário", "salario", "folha", "pessoal", "funcionário", "funcionario", "FGTS", "VT", "VR", "CLT", "PJ", "freelancer", "quanto ganha", "quanto paga", "custo do", "custo da".

- **GENERAL**: Greetings, "help", "who are you", navigation requests (e.g. "me leva para..."), questions about how to use the system, or clearly off-topic.

CROSS-DOMAIN: If the question involves both financial AND stock/sales data (e.g., "compare vendas com despesas"), prefer FINANCE because the finance agent has query_database that can access ALL tables including historico_vendas, estoque, and perdas.

MULTI-DOMAIN: If the question CLEARLY spans two domains (e.g., "compare estoque com despesas", "quanto produzimos vs quanto vendemos"), return BOTH domains separated by +: { "domain": "STOCK+FINANCE", "reasoning": "..." }. Only use multi-domain when the answer genuinely requires data from both. Most questions should still route to a single domain.
${contextHint}

**Output Format:**
Return ONLY a JSON object: { "domain": "DOMAIN_NAME", "reasoning": "brief explanation" }`
}

// ============================================================================
// KEYWORD PRE-ROUTER — evita LLM call pra queries single-domain óbvias.
// Salva ~400ms. LLM router cuida de multi-domain e ambíguos.
//
// REGRA CRÍTICA: só pre-roteia quando EXATAMENTE 1 domínio tem match.
// Se 2+ domínios têm keywords (ex: "encomendas + notas fiscais") →
// retorna null → LLM router detecta multi-domain → ambos os agents rodam
// em paralelo → coordinator sintetiza. Cross-domain funciona 100%.
// ============================================================================
function keywordPreRoute(message: string, pageContext?: any): { domain: string; reasoning: string } | null {
    const msg = message.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')

    // Detecta keywords por domínio
    const matches: string[] = []

    if (/\b(conta[s]?\s+(a\s+)?(pagar|receber)|despesa|receita|dre|fatura|extrato|bancari|cartao|cofre|folha|salario|fgts|inss|vale\s+(transporte|refeicao)|pix\s+enviado|transferencia|vencimento|vencida|inadimplente|concilia|nota\s+fiscal)\b/.test(msg)) {
        matches.push('FINANCE')
    }

    if (/\b(encomenda|requisicao|separacao|expedicao|delivery|retirada|torre\s+de\s+controle|separando|expedindo|picking)\b/.test(msg)) {
        matches.push('LOGISTICS')
    }

    // STOCK: keywords explícitos OU (contagem/temos + alvo conhecido como
    // nome de loja Momma, "bombom", "produto", "tem"). Sem isso, "quantos
    // bombons em asa norte" caía no LLM router que classificava inconsistente
    // ("lago sul" → STOCK ✓; "asa norte" → GENERAL ✗). Bug confirmado em
    // mia_query_logs 2026-05-19.
    if (/\b(estoque|camara\s+fria|validade|vencendo|perda|lote|movimentacao|producao\s+diaria|producao\s+da\s+fabrica)\b/.test(msg)
        || /\b(quanto|quantos|quantas)\b.*\b(temos|tem|existe[m]?|h[áa])\b/.test(msg)
        || /\b(quanto|quantos|quantas)\s+\S+\s+(em|na|no|de|da|do)\b.*\b(asa\s+(sul|norte)|lago\s+sul|aguas\s+claras|brasilia\s+shopping|fabrica|loja)\b/i.test(msg)
        || /\b(asa\s+(sul|norte)|lago\s+sul|aguas\s+claras|brasilia\s+shopping|fabrica|brunch)\b.*\b(estoque|saldo|tem|temos|bombom|produto|gelato|brownie|torta|bolo|brigadeiro|beijinho|brigadinho)\b/i.test(msg)
        || /\b(bombom|brigadeiro|beijinho|gelato|brownie|brigadinho|torta|bolo|salgado|pao|paozinho|insumo|materia\s+prima)\b.*\b(quantos?|quantas?|temos|tem|saldo|estoque|na\s+loja|em)\b/i.test(msg)
    ) {
        matches.push('STOCK')
    }

    if (/\b(catalogo|preco\s+(de\s+)?(custo|venda)|setor\s+do\s+produto|cadastro\s+de\s+produto|criar\s+produto|atualizar\s+produto|desativar\s+produto)\b/.test(msg)) {
        matches.push('CATALOG')
    }

    // Multi-domain detectado → passa pro LLM router que faz o coordinator
    if (matches.length > 1) {
        console.log(`[ROUTER] Multi-domain keywords detected (${matches.join('+')}) — passing to LLM router`)
        return null
    }

    // Single domain → pre-route diretamente
    if (matches.length === 1) {
        return { domain: matches[0], reasoning: `keyword_${matches[0].toLowerCase()}` }
    }

    // GENERAL — saudações, navegação simples
    if (/^(oi|ola|bom\s+dia|boa\s+tarde|boa\s+noite|tudo\s+bem|quem\s+e\s+voce|me\s+leva|abre|navega|acessar|ir\s+para|menu|ajuda)\b/.test(msg) && msg.length < 50) {
        return { domain: 'GENERAL', reasoning: 'keyword_general' }
    }

    // Page context bias só após verificar que não é cross-domain
    // (ex: user em /financeiro mas query tem palavras de logística → LLM decide)
    const route = (pageContext?.route || '').toLowerCase()
    if (matches.length === 0 && msg.length < 40) {
        if (route.includes('financeiro') || route.includes('notas-fiscais') || route.includes('extrato')) {
            return { domain: 'FINANCE', reasoning: 'page_context_short_query' }
        }
        if (route.includes('logistica') || route.includes('encomenda') || route.includes('requisicao')) {
            return { domain: 'LOGISTICS', reasoning: 'page_context_short_query' }
        }
        if (route.includes('estoque') || route.includes('producao')) {
            return { domain: 'STOCK', reasoning: 'page_context_short_query' }
        }
        if (route.includes('produto')) {
            return { domain: 'CATALOG', reasoning: 'page_context_short_query' }
        }
    }

    return null // LLM router
}

export async function routeMessage(message: string, history: any[], pageContext?: any): Promise<{ domain: string; domains: string[]; reasoning: string }> {
    // Fast path: keyword pre-routing (no LLM call for obvious queries)
    const preRouted = keywordPreRoute(message, pageContext)
    console.log(`[ROUTER-DEBUG] message="${message.slice(0, 100)}" preRouted=${JSON.stringify(preRouted)}`)
    if (preRouted) {
        console.log(`[ROUTER] Pre-routed to ${preRouted.domain} via keywords (${preRouted.reasoning})`)
        return { domain: preRouted.domain, domains: [preRouted.domain], reasoning: preRouted.reasoning }
    }

    const recentHistory = history.slice(0, 3).map(m => ({ role: m.role, content: m.content }))

    const messages = [
        { role: 'system', content: buildRouterPrompt(pageContext) },
        ...recentHistory,
        { role: 'user', content: message }
    ]

    try {
        const response = await callLLM(messages, [], "x-ai/grok-4.1-fast", 0)
        let content = response.content.replace(/```json/g, '').replace(/```/g, '').trim()
        const parsed = JSON.parse(content)
        const domainStr = parsed.domain || 'GENERAL'
        // Split multi-domain: "STOCK+FINANCE" -> ["STOCK", "FINANCE"]
        const domains = domainStr.split('+').map((d: string) => d.trim())
        return { domain: domains[0], domains, reasoning: parsed.reasoning || '' }
    } catch (e) {
        console.error('[ROUTER] Error routing message:', e)
        return { domain: 'GENERAL', domains: ['GENERAL'], reasoning: 'Error in router, defaulting to general.' }
    }
}

