async function runDomainAgent(domain: string, agentMessages: any[], supabaseClient: any, finalContext: string, telegramCtx: string, blockedFinanceTools?: string[], pageRoute?: string): Promise<string> {
    if (domain === 'STOCK') {
        return await runStockAgent(agentMessages, supabaseClient, finalContext)
    } else if (domain === 'CATALOG') {
        return await runCatalogAgent(agentMessages, supabaseClient, finalContext)
    } else if (domain === 'FINANCE') {
        return await runFinanceAgent(agentMessages, supabaseClient, finalContext, blockedFinanceTools, pageRoute)
    } else if (domain === 'LOGISTICS') {
        return await runLogisticsAgent(agentMessages, supabaseClient, finalContext)
    } else {
        // GENERAL domain — estático (prompt) separado do dinâmico (contexto) pra cache hit
        const basePrompt = telegramCtx ? TELEGRAM_SYSTEM : GENERAL_SYSTEM
        const systemMsgs = buildSystemMessages(basePrompt, finalContext)
        const res = await callLLM([...systemMsgs, ...agentMessages], [], "x-ai/grok-4.1-fast")
        return res.content || ''
    }
}

async function processMessage(
    text: string,
    agentMessages: any[],
    supabaseClient: any,
    pageContext?: any,
    pendingActions?: any[]
): Promise<{ responseText: string; domain: string; reasoning: string }> {
    const _queryStartTime = Date.now()
    // MIA is open to all users — domain-level access is enforced below via canAccessDomain
    const userPerms: string[] = pageContext?._userPermissions || []
    const userRole: string = pageContext?._userRole || 'unknown'

    // Route with page context awareness
    const { domain, domains, reasoning } = await routeMessage(text, agentMessages, pageContext)
    console.log(`[MIA] Routed to: ${domain}${domains.length > 1 ? ` (multi: ${domains.join('+')})` : ''} (${reasoning})`)

    if (domains && domains.length > 1) {
        // Multi-domain: filter out domains the user can't access
        const allowedDomains = domains.filter((d: string) => canAccessDomain(d, userPerms, userRole))
        const blockedDomains = domains.filter((d: string) => !canAccessDomain(d, userPerms, userRole))
        if (allowedDomains.length === 0) {
            console.log(`[MIA] ACCESS DENIED: user role=${userRole} blocked from ${domains.join('+')}`)
            return { responseText: getAccessDeniedMessage(domains[0]), domain, reasoning }
        }
        if (blockedDomains.length > 0) {
            console.log(`[MIA] Partial access: allowing ${allowedDomains.join('+')} but blocking ${blockedDomains.join('+')}`)
            // Only run allowed domains
            domains.length = 0
            domains.push(...allowedDomains)
        }
    } else if (!canAccessDomain(domain, userPerms, userRole)) {
        console.log(`[MIA] ACCESS DENIED: user role=${userRole} blocked from ${domain}`)
        return { responseText: getAccessDeniedMessage(domain), domain, reasoning }
    }

    // Build dynamic context for domain agents (page state + pending actions)
    const dynamicContext = pageContext ? buildDynamicContext(pageContext, pendingActions || []) : ''

    // Telegram channel gets its own context injection
    const telegramCtx = pageContext?._telegramContext || ''
    let finalContext = dynamicContext + telegramCtx

    // Role-specific context injection — adapts agent tone/depth by user role
    const roleContext = buildRoleContext(pageContext?._userRole || '')
    if (roleContext) finalContext += roleContext

    // Hermes knowledge injection
    try {
        const hermesKnowledge = await queryHermes(supabaseClient)
        if (hermesKnowledge) {
            finalContext += `\n\n--- CONHECIMENTO APRENDIDO (insights internos) ---\n${hermesKnowledge}`
        }
    } catch {}

    // ── Compute blocked finance tools for partial access (e.g., NF without Financeiro) ──
    const blockedFinanceTools: string[] = []
    if (!isAdmin(userRole) && !userPerms.includes('view_financeiro') && userPerms.includes('view_notas_fiscais')) {
        // User can see NFs but not the full financial module → block salary/DRE/bank tools
        blockedFinanceTools.push(...FINANCE_RESTRICTED_TOOLS)
        console.log(`[MIA] Partial finance access: blocking ${blockedFinanceTools.length} restricted tools (NF-only user)`)
    }

async function runCoordinator(
    userQuery: string,
    specialistResults: Array<{ domain: string; text: string }>,
    contextBlock: string,
): Promise<string> {
    const findings = specialistResults
        .map(r => `## Specialist: ${r.domain}\n${r.text}`)
        .join('\n\n---\n\n')
    const userContent = `Pergunta do usuário:\n"${userQuery}"\n\nFindings dos specialists:\n\n${findings}${contextBlock ? `\n\n<context>\n${contextBlock}\n</context>` : ''}`
    try {
        const res = await callLLM(
            [
                { role: 'system', content: COORDINATOR_PROMPT },
                { role: 'user', content: userContent },
            ],
            [],
            'x-ai/grok-4.1-fast',
            0,
        )
        const out = (res?.content || '').trim()
        if (!out) return specialistResults.map(r => r.text).join('\n\n')
        return out
    } catch (e) {
        console.warn('[MIA] coordinator failed, fallback to concat:', e)
        return specialistResults.map(r => r.text).join('\n\n')
    }
}

