// ── Action badge component ───────────────────────────────────

function ActionBadge({ action, executed }: { action: MiaAction; executed?: boolean }) {
  const config = ACTION_LABELS[action.type] || { label: action.type, icon: Navigation };
  const Icon = config.icon;

  return (
    <Badge
      variant="outline"
      className={cn(
        "text-[11px] gap-1 font-normal py-0.5 px-2",
        executed
          ? "border-emerald-500/30 text-emerald-700 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-950/30"
          : "border-border/50 text-muted-foreground"
      )}
    >
      {executed ? <CheckCircle2 className="h-3 w-3" /> : <Icon className="h-3 w-3" />}
      {action.description || config.label}
    </Badge>
  );
}

// ── Copy button for code blocks ──────────────────────────────

function CopyButton({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);
  const handleCopy = useCallback(() => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }, [text]);

  return (
    <button
      onClick={handleCopy}
      className="absolute top-2 right-2 p-1 rounded-md bg-white/10 hover:bg-white/20 text-gray-400 hover:text-gray-200 transition-colors"
      title="Copiar"
    >
      {copied ? <Check className="h-3.5 w-3.5" /> : <Copy className="h-3.5 w-3.5" />}
    </button>
  );
}

// ── Markdown renderer components ─────────────────────────────

const markdownComponents = {
  // Headings
  h1: ({ children, ...props }: any) => (
    <h3 className="text-base font-semibold text-foreground mt-3 mb-1.5 first:mt-0" {...props}>{children}</h3>
  ),
  h2: ({ children, ...props }: any) => (
    <h4 className="text-sm font-semibold text-foreground mt-2.5 mb-1 first:mt-0" {...props}>{children}</h4>
  ),
  h3: ({ children, ...props }: any) => (
    <h5 className="text-sm font-medium text-foreground mt-2 mb-1 first:mt-0" {...props}>{children}</h5>
  ),

  // Paragraphs — use div to avoid invalid nesting (pre/div inside p)
  p: ({ children, ...props }: any) => (
    <div className="text-[13px] leading-relaxed text-foreground/90 mb-2 last:mb-0" {...props}>{children}</div>
  ),

  // Strong / Bold
  strong: ({ children, ...props }: any) => (
    <strong className="font-semibold text-foreground" {...props}>{children}</strong>
  ),

  // Emphasis / Italic
  em: ({ children, ...props }: any) => (
    <em className="italic text-foreground/80" {...props}>{children}</em>
  ),

  // Unordered lists
  ul: ({ children, ...props }: any) => (
    <ul className="space-y-1 mb-2 last:mb-0" {...props}>{children}</ul>
  ),

  // Ordered lists
  ol: ({ children, ...props }: any) => (
    <ol className="space-y-1 mb-2 last:mb-0 list-decimal list-inside" {...props}>{children}</ol>
  ),

  // List items
  li: ({ children, ...props }: any) => (
    <li className="text-[13px] leading-relaxed text-foreground/90 flex items-start gap-1.5" {...props}>
      <span className="text-emerald-500 mt-1.5 shrink-0 text-[8px]">●</span>
      <span className="flex-1">{children}</span>
    </li>
  ),

  // Code — inline and block
  code: ({ inline, className, children, node, ...props }: any) => {
    // Detect block code: has className (language-xxx) or multi-line content
    const isBlock = !inline && (className || String(children).includes('\n'));

    if (!isBlock) {
      return (
        <code
          className="px-1.5 py-0.5 rounded-md bg-emerald-500/10 text-emerald-700 dark:text-emerald-300 text-xs font-mono"
          {...props}
        >
          {children}
        </code>
      );
    }

    const text = String(children).replace(/\n$/, '');
    return (
      <div className="relative group my-2 not-prose">
        <CopyButton text={text} />
        <pre className="rounded-lg bg-zinc-900 dark:bg-zinc-950 border border-zinc-800 p-3 overflow-x-auto">
          <code className="text-xs font-mono text-zinc-300 leading-relaxed" {...props}>
            {children}
          </code>
        </pre>
      </div>
    );
  },

  // Block quotes (used for callouts / tips)
  blockquote: ({ children, ...props }: any) => (
    <div
      className="border-l-2 border-emerald-500/50 bg-emerald-500/5 rounded-r-lg pl-3 pr-3 py-2 my-2 text-[13px]"
      {...props}
    >
      {children}
    </div>
  ),

  // Horizontal rule
  hr: (props: any) => (
    <hr className="border-border/30 my-3" {...props} />
  ),

  // Tables
  table: ({ children, ...props }: any) => (
    <div className="overflow-x-auto my-2 rounded-lg border border-border/40">
      <table className="w-full text-xs" {...props}>{children}</table>
    </div>
  ),
  thead: ({ children, ...props }: any) => (
    <thead className="bg-muted/40" {...props}>{children}</thead>
  ),
  th: ({ children, ...props }: any) => (
    <th className="px-2.5 py-1.5 text-left font-medium text-foreground/70 text-[11px] uppercase tracking-wider" {...props}>{children}</th>
  ),
  td: ({ children, ...props }: any) => (
    <td className="px-2.5 py-1.5 border-t border-border/20 text-foreground/80" {...props}>{children}</td>
  ),

  // Links
  a: ({ children, href, ...props }: any) => (
    <a
      href={href}
      target="_blank"
      rel="noopener noreferrer"
      className="text-emerald-600 dark:text-emerald-400 underline underline-offset-2 hover:text-emerald-700 dark:hover:text-emerald-300 transition-colors"
      {...props}
    >
      {children}
    </a>
  ),
};

// ── Main message bubble ──────────────────────────────────────

export const MiaChatMessageBubble = memo(function MiaChatMessageBubble({
  message,
  onClarificationAnswer,
}: {
  message: MiaChatMessage;
  onClarificationAnswer?: (messageId: string, value: string, label: string) => void;
}) {
  const isUser = message.role === 'user';

  const remarkPlugins = useMemo(() => [remarkGfm], []);

  return (
    <div className={cn("flex gap-2.5", isUser ? "justify-end" : "justify-start")}>
      {/* Avatar — assistant */}
      {!isUser && (
        <div className="h-7 w-7 rounded-full bg-gradient-to-br from-emerald-500 to-teal-600 flex items-center justify-center shrink-0 mt-0.5 shadow-sm">
          <Sparkles className="h-3.5 w-3.5 text-white" />
        </div>
      )}

      <div className={cn("max-w-[88%] space-y-1.5")}>
        {/* Message content */}
        {isUser ? (
          /* ── User bubble: plain text ── */
          <div className="rounded-2xl rounded-br-md px-3.5 py-2 text-[13px] leading-relaxed bg-emerald-600 text-white shadow-sm">
            <p className="whitespace-pre-wrap">{message.content}</p>
          </div>
        ) : (
          /* ── Assistant bubble: rich markdown ── */
          <div className="rounded-2xl rounded-bl-md px-4 py-3 bg-card border border-border/40 shadow-sm">
            <div className="mia-markdown prose-sm max-w-none">
              <ReactMarkdown
                remarkPlugins={remarkPlugins}
                components={markdownComponents}
              >
                {message.content}
              </ReactMarkdown>
            </div>
          </div>
        )}

        {/* Action badges */}
        {message.actions && message.actions.length > 0 && (
          <div className="flex flex-wrap gap-1 px-1">
            {message.actions.map((action, i) => (
              <ActionBadge key={i} action={action} executed={message.actionsExecuted} />
            ))}
          </div>
        )}

        {/* Clarification chips (ask_clarification) */}
        {!isUser && message.clarification && onClarificationAnswer && (
          <MiaClarificationChips
            clarification={message.clarification}
            onAnswer={(value, label) => onClarificationAnswer(message.id, value, label)}
          />
        )}

        {/* Timestamp */}
        <p className="text-[10px] text-muted-foreground/60 px-1">
          {message.timestamp.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}
        </p>
      </div>

      {/* Avatar — user */}
      {isUser && (
        <div className="h-7 w-7 rounded-full bg-primary/10 flex items-center justify-center shrink-0 mt-0.5">
          <User className="h-3.5 w-3.5 text-primary" />
        </div>
      )}
    </div>
  );
});

