import React, { useRef, useEffect, useMemo } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import { Sparkles, Play } from 'lucide-react';
import { MiaChatMessage, MiaExecutionStep, MiaAgentRound, MiaTaskPlan, MiaAction } from '@/types/mia';
import { MiaMessageBubble } from './MiaMessageBubble';
import { MiaStreamingMessage } from './MiaStreamingMessage';
import { Button } from '@/shared/ui/button';

interface MiaMessageListProps {
  messages: MiaChatMessage[];
  isStreaming: boolean;
  streamingText: string;
  streamingStatus: string | null;
  thinkingBlocks: { round: number; content: string; durationMs: number }[];
  agentRounds: MiaAgentRound[];
  executionSteps: MiaExecutionStep[];
  activeTaskPlan: MiaTaskPlan | null;
  pendingConfirmation: { actions: MiaAction[]; messageId: string } | null;
  onConfirm: () => Promise<void>;
  onCancelConfirm: () => void;
  onApproveTask: () => Promise<void>;
  onCancelTask: () => void;
  onClarificationAnswer?: (messageId: string, value: string, label: string) => void;
  emptyState: React.ReactNode;
}

/**
 * TaskPlanCard — Preview de plano de ação
 */
const TaskPlanCard = ({ plan, onApprove, onCancel }: { plan: MiaTaskPlan; onApprove: () => void; onCancel: () => void; }) => (
  <div className="ml-[40px] mb-8 rounded-2xl border border-[--mia-success]/30 bg-[--mia-success-subtle]/30 overflow-hidden shadow-sm">
    <div className="px-4 py-3 border-b border-[--mia-success]/20 flex items-center justify-between bg-white/50">
      <div className="flex items-center gap-2">
        <Play className="h-4 w-4 text-[--mia-success]" />
        <span className="text-sm font-bold text-[--mia-text-primary] font-momma">{plan.title}</span>
      </div>
    </div>
    <div className="p-3 space-y-2 max-h-48 overflow-y-auto">
      {plan.items.map((item, i) => (
        <div key={i} className="flex items-center gap-3 px-2 py-1.5 rounded-xl bg-white/40 text-[13px] font-medium text-[--mia-text-secondary]">
          <div className="h-1.5 w-1.5 rounded-full bg-[--mia-success]" />
          <span className="truncate flex-1">{item.label}</span>
        </div>
      ))}
    </div>
    <div className="px-4 py-3 bg-white/60 border-t border-[--mia-success]/20 flex items-center justify-end gap-3">
      <Button data-mia-action="on-cancel" variant="ghost" size="sm" onClick={onCancel} className="h-8 text-[11px] font-bold uppercase tracking-wider text-[--mia-text-muted] hover:text-destructive">
        Cancelar
      </Button>
      <Button data-mia-action="on-approve" size="sm" onClick={onApprove} className="h-8 text-[11px] font-bold uppercase tracking-wider bg-[--mia-success] hover:bg-[--mia-success]/90 text-white px-4 rounded-xl">
        Aprovar e Executar
      </Button>
    </div>
  </div>
);

/**
 * ConfirmationCard — Confirmação de ações perigosas
 */
const ConfirmationCard = ({ actions, onConfirm, onCancel }: { actions: MiaAction[]; onConfirm: () => void; onCancel: () => void; }) => (
  <div className="ml-[40px] mb-8 rounded-2xl border border-amber-500/30 bg-amber-50/50 overflow-hidden shadow-sm">
    <div className="px-4 py-3 border-b border-amber-500/20 flex items-center gap-2 bg-white/50">
      <Sparkles className="h-4 w-4 text-amber-500" />
      <span className="text-sm font-bold text-[--mia-text-primary] font-momma">Confirmação Necessária</span>
    </div>
    <div className="p-4 text-sm text-[--mia-text-secondary] font-medium leading-relaxed">
      A MIA propôs {actions.length} {actions.length === 1 ? 'ação que requer' : 'ações que requerem'} sua aprovação antes de prosseguir.
    </div>
    <div className="px-4 py-3 bg-white/60 border-t border-amber-500/20 flex items-center justify-end gap-3">
      <Button data-mia-action="on-cancel" variant="ghost" size="sm" onClick={onCancel} className="h-8 text-[11px] font-bold uppercase tracking-wider text-[--mia-text-muted]">
        Ignorar
      </Button>
      <Button data-mia-action="on-confirm" size="sm" onClick={onConfirm} className="h-8 text-[11px] font-bold uppercase tracking-wider bg-amber-500 hover:bg-amber-600 text-white px-4 rounded-xl shadow-md shadow-amber-500/20">
        Confirmar Ações
      </Button>
    </div>
  </div>
);

/**
 * MemoizedBubble — Evita re-renderizações desnecessárias de mensagens já concluídas.
 * Inclui clarification.resolved para re-renderizar quando user clica numa opção.
 */
const MemoizedBubble = React.memo(MiaMessageBubble, (prev, next) =>
  prev.message.id === next.message.id &&
  prev.isLast === next.isLast &&
  prev.message.actionsExecuted === next.message.actionsExecuted &&
  prev.message.clarification?.resolved === next.message.clarification?.resolved &&
  prev.onClarificationAnswer === next.onClarificationAnswer
);

export function MiaMessageList({
  messages,
  isStreaming,
  streamingText,
  streamingStatus,
  thinkingBlocks,
  agentRounds,
  executionSteps,
  activeTaskPlan,
  pendingConfirmation,
  onConfirm,
  onCancelConfirm,
  onApproveTask,
  onCancelTask,
  onClarificationAnswer,
  emptyState
}: MiaMessageListProps) {
  const scrollRef = useRef<HTMLDivElement>(null);

  // Auto-scroll para o final em novos conteúdos
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isStreaming, streamingText, streamingStatus, thinkingBlocks, agentRounds, executionSteps]);

  if (messages.length === 0 && !isStreaming) {
    return (
      <div className="flex-1 overflow-y-auto overflow-x-hidden scroll-smooth scrollbar-thin scrollbar-thumb-[--mia-glass-border] hover:scrollbar-thumb-[--mia-accent]/20">
        {emptyState}
      </div>
    );
  }

  return (
    <div 
      ref={scrollRef}
      className="flex-1 overflow-y-auto overflow-x-hidden scroll-smooth scrollbar-thin scrollbar-thumb-[--mia-glass-border] hover:scrollbar-thumb-[--mia-accent]/20"
    >
      <div className="max-w-3xl mx-auto px-4 pt-8 pb-32">
        <AnimatePresence initial={false}>
          {/* Mensagens concluídas */}
          {messages.map((m, i) => (
            <MemoizedBubble
              key={m.id || i}
              message={m}
              isLast={i === messages.length - 1 && !isStreaming}
              onClarificationAnswer={onClarificationAnswer}
            />
          ))}

          {/* ── STREAMING: Uma única MiaStreamingMessage enquanto isStreaming === true ── */}
          {isStreaming && (
            <MiaStreamingMessage
              key="streaming-message"
              streamingText={streamingText}
              streamingStatus={streamingStatus}
              thinkingBlocks={thinkingBlocks}
              agentRounds={agentRounds}
              executionSteps={executionSteps}
            />
          )}

          {/* Interactive UI Cards */}
          {pendingConfirmation && (
            <ConfirmationCard 
              key="pending-confirmation"
              actions={pendingConfirmation.actions} 
              onConfirm={onConfirm} 
              onCancel={onCancelConfirm} 
            />
          )}

          {activeTaskPlan && (
            <TaskPlanCard 
              key="active-task-plan"
              plan={activeTaskPlan} 
              onApprove={onApproveTask} 
              onCancel={onCancelTask} 
            />
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}

