// MIA Streaming Message — 1 card timeline glass único.
//
// Anti-pattern eliminado: antes tinha 3 componentes mostrando passos
// (MiaThinkingBlock + GlassBoxInlineSteps + execution lista). User reclamou
// de bagunça. Agora: 1 timeline glass collapsible subway-map (igual Devin/
// Cursor 3) que mistura thinking + tool calls + DOM steps (watchLog).
//
// Header: pulse dot + "MIA atuando/raciocinando" + counter + chevron
// Body: timeline vertical com connector line, icon por step, status color
// Footer: nothing — só streaming text logo abaixo se houver

import React from 'react';
import { motion } from 'framer-motion';
import { Sparkles } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { MiaAgentRound, MiaExecutionStep } from '@/types/mia';
import { miaMarkdownComponents } from './mia-markdown-components';
import { miaMotion } from './mia-animations';
import { useMiaGlassBoxContext } from '@/shared/contexts/MiaContext';
import { MiaStepsTimeline } from './MiaStepsTimeline';

interface MiaStreamingMessageProps {
  streamingText: string;
  streamingStatus: string | null;
  thinkingBlocks: { round: number; content: string; durationMs: number }[];
  agentRounds: MiaAgentRound[];
  executionSteps: MiaExecutionStep[];
}

export function MiaStreamingMessage({
  streamingText,
  thinkingBlocks,
  agentRounds,
  executionSteps,
}: MiaStreamingMessageProps) {
  const { watchLog } = useMiaGlassBoxContext();
  const hasText = streamingText.length > 0;

  return (
    <motion.div
      variants={miaMotion.message}
      initial="initial"
      animate="animate"
      className="mb-8 w-full group"
    >
      {/* Avatar + Nome */}
      <div className="flex items-center gap-2.5 mb-3">
        <div className="relative">
          <div className="h-7 w-7 rounded-lg bg-gradient-to-br from-[--mia-accent] to-[--mia-thinking-to] flex items-center justify-center shadow-sm z-10 relative">
            <Sparkles className="h-3.5 w-3.5 text-white animate-pulse" />
          </div>
          <div className="absolute inset-0 rounded-lg bg-gradient-to-br from-[--mia-accent] to-[--mia-thinking-to] opacity-20 blur-md animate-pulse" />
        </div>
        <span className="text-xs font-bold text-[--mia-text-secondary] uppercase tracking-wider">MIA</span>
      </div>

      {/* Timeline glass (componente standalone reusado em MiaMessageBubble persistente) */}
      <div className="ml-[38px] mb-3 max-w-[95%]">
        <MiaStepsTimeline
          thinkingBlocks={thinkingBlocks}
          agentRounds={agentRounds}
          executionSteps={executionSteps}
          watchLog={watchLog}
          isStreaming={true}
          defaultExpanded={true}
        />
      </div>

      {/* ── STREAMING TEXT ── */}
      {hasText && (
        <div className="pl-[38px] mt-2">
          <div className="prose-mia max-w-none">
            <ReactMarkdown
              remarkPlugins={[remarkGfm]}
              components={miaMarkdownComponents}
            >
              {streamingText}
            </ReactMarkdown>
            <span className="mia-cursor" />
          </div>
        </div>
      )}
    </motion.div>
  );
}

