1	// MIA Steps Timeline — card glass collapsible persistente.
2	//
3	// Usado em 2 lugares:
4	//  1. MiaStreamingMessage — durante stream (live data do contexto)
5	//  2. MiaMessageBubble — persistente após stream (snapshot salvo no message)
6	//
7	// Visual: card glass fantasma com fade leve. Timeline subway-map vertical
8	// (connector line + icon por step + status color). Default expanded.
9	// Animação smooth fade-in. Estilo silicon valley (Devin / Cursor 3 / Linear).
10	
11	import React, { useState, useMemo } from 'react';
12	import {
13	  Sparkles, ChevronDown, MousePointer2, Type, ChevronsDown,
14	  ArrowRight, MoveDown, Hourglass, Brain, CheckCircle2, AlertCircle,
15	  Loader2, Zap, Copy, Check,
16	} from 'lucide-react';
17	import { cn } from '@/shared/lib/utils';
18	import type { MiaAgentRound, MiaExecutionStep, MiaWatchLogEntry } from '@/types/mia';
19	
20	export interface UnifiedStep {
21	  id: string;
22	  kind: 'think' | 'tool' | 'dom' | 'exec';
23	  label: string;
24	  status: 'pending' | 'running' | 'success' | 'error' | 'info' | 'warning';
25	  meta?: string;
26	}
27	
28	function iconForStep(step: UnifiedStep) {
29	  if (step.kind === 'think') return Brain;
30	  if (step.kind === 'dom') {
31	    const m = step.label.toLowerCase();
32	    if (m.includes('clicando') || m.includes('clicado')) return MousePointer2;
33	    if (m.includes('preenchendo') || m.includes('preenchido')) return Type;
34	    if (m.includes('selecionando') || m.includes('selecionado')) return ChevronsDown;
35	    if (m.includes('scroll')) return MoveDown;
36	    if (m.includes('aguardando') || m.includes('apareceu')) return Hourglass;
37	    if (m.includes('navegando') || m.includes('→')) return ArrowRight;
38	  }
39	  if (step.kind === 'tool') return Zap;
40	  return Sparkles;
41	}
42	
43	function statusColor(status: UnifiedStep['status']) {
44	  switch (status) {
45	    case 'running': return 'text-[--mia-accent]';
46	    case 'success': return 'text-emerald-500';
47	    case 'error': return 'text-red-500';
48	    case 'warning': return 'text-amber-500';
49	    case 'info': return 'text-[--mia-text-muted]';
50	    default: return 'text-[--mia-text-muted]';
51	  }
52	}
53	
54	function borderColor(status: UnifiedStep['status'], isActive: boolean) {
55	  if (isActive) return 'border-l-[--mia-accent]';
56	  switch (status) {
57	    case 'success': return 'border-l-emerald-500/30';
58	    case 'error': return 'border-l-red-500/50';
59	    case 'warning': return 'border-l-amber-500/40';
60	    default: return 'border-l-[--mia-glass-border]';
61	  }
62	}
63	
64	function StatusDot({ status }: { status: UnifiedStep['status'] }) {
65	  const Icon = status === 'running' ? Loader2
66	    : status === 'success' ? CheckCircle2
67	    : status === 'error' ? AlertCircle
68	    : status === 'warning' ? AlertCircle
69	    : null;
70	  if (!Icon) return null;
71	  return (
72	    <div className="absolute -bottom-0.5 -right-0.5 h-3.5 w-3.5 rounded-full bg-[--mia-bg-elevated] flex items-center justify-center shadow-sm">
73	      <Icon className={cn('h-2 w-2', statusColor(status), status === 'running' && 'animate-spin')} />
74	    </div>
75	  );
76	}
77	
78	function StepRow({ step, isActive }: { step: UnifiedStep; isActive: boolean }) {
79	  const TypeIcon = iconForStep(step);
80	  return (
81	    <div className={cn(
82	      'relative flex gap-3 pl-3 border-l-2 transition-colors',
83	      isActive ? 'border-l-[--mia-accent] border-l-[2.5px]' : borderColor(step.status, isActive),
84	    )}>
85	      <div className={cn(
86	        'absolute left-0 -translate-x-1/2 w-5 h-5 rounded-full flex items-center justify-center',
87	        'bg-[--mia-bg-elevated] border border-[--mia-glass-border]',
88	      )} style={{ top: '8px' }}>
89	        <TypeIcon className={cn('h-3 w-3', statusColor(step.status))} />
90	        <StatusDot status={step.status} />
91	      </div>
92	      <div className="flex-1 py-1.5 pr-2 min-w-0">
93	        <div className="flex items-center gap-2">
94	          <span className="text-[11px] text-[--mia-text-primary] flex-1 truncate leading-snug">
95	            {step.label}
96	          </span>
97	          {step.meta && (
98	            <span className="text-[10px] text-[--mia-text-muted] tabular-nums shrink-0">
99	              {step.meta}
100	            </span>
101	          )}
102	        </div>
103	      </div>
104	    </div>
105	  );
106	}
107	
108	interface MiaStepsTimelineProps {
109	  thinkingBlocks?: { round: number; content: string; durationMs: number }[];
110	  agentRounds?: MiaAgentRound[];
111	  executionSteps?: MiaExecutionStep[];
112	  watchLog?: MiaWatchLogEntry[];
113	  /** true durante stream live; false quando snapshot persistente */
114	  isStreaming?: boolean;
115	  /** Default expand state. Live: true. Snapshot: false (collapsed). */
116	  defaultExpanded?: boolean;
117	  /** Mostra botão "Copiar" no header (snapshot persistente). */
118	  allowCopy?: boolean;
119	}
120	
121	export function MiaStepsTimeline({
122	  thinkingBlocks = [],
123	  agentRounds = [],
124	  executionSteps = [],
125	  watchLog = [],
126	  isStreaming = false,
127	  defaultExpanded,
128	  allowCopy = false,
129	}: MiaStepsTimelineProps) {
130	  const [expanded, setExpanded] = useState(defaultExpanded ?? isStreaming);
131	  const [copied, setCopied] = useState(false);
132	
133	  const allSteps: UnifiedStep[] = useMemo(() => {
134	    const steps: UnifiedStep[] = [];
135	    agentRounds.forEach((round) => {
136	      const think = thinkingBlocks.find(t => t.round === round.round);
137	      if (think) {
138	        steps.push({
139	          id: `think-${round.round}`,
140	          kind: 'think',
141	          label: `Raciocínio (round ${round.round})`,
142	          status: round.state === 'completed' ? 'success' : round.state === 'error' ? 'error' : 'running',
143	          meta: `${(think.durationMs / 1000).toFixed(1)}s`,
144	        });
145	      }
146	      round.tools.forEach((tool, ti) => {
147	        steps.push({
148	          id: `tool-${round.round}-${ti}`,
149	          kind: 'tool',
150	          label: (tool.name || 'ferramenta').replace(/_/g, ' '),
151	          status: tool.status === 'running' ? 'running'
152	            : tool.status === 'success' || tool.success === true ? 'success'
153	            : tool.status === 'error' || tool.success === false ? 'error'
154	            : 'info',
155	        });
156	      });
157	    });
158	    executionSteps.forEach((step, i) => {
159	      steps.push({
160	        id: `exec-${i}`,
161	        kind: 'exec',
162	        label: step.label,
163	        status: step.status === 'running' ? 'running'
164	          : step.status === 'success' ? 'success'
165	          : step.status === 'error' ? 'error'
166	          : 'info',
167	      });
168	    });
169	    watchLog.forEach((entry) => {
170	      steps.push({
171	        id: entry.id,
172	        kind: 'dom',
173	        label: entry.message,
174	        status: entry.status === 'in_progress' ? 'running'
175	          : entry.status === 'success' ? 'success'
176	          : entry.status === 'error' ? 'error'
177	          : entry.status === 'warning' ? 'warning'
178	          : 'info',
179	      });
180	    });
181	    return steps;
182	  }, [thinkingBlocks, agentRounds, executionSteps, watchLog]);
183	
184	  if (allSteps.length === 0) return null;
185	
186	  const isRunning = allSteps.some(s => s.status === 'running');
187	  const activeIdx = allSteps.map(s => s.status).lastIndexOf('running');
188	
189	  const handleCopy = async (e: React.MouseEvent) => {
190	    e.stopPropagation(); // não toggle expanded
191	    const text = allSteps.map((s, i) => {
192	      const statusEmoji = s.status === 'success' ? '✓'
193	        : s.status === 'error' ? '✗'
194	        : s.status === 'running' ? '⏳'
195	        : s.status === 'warning' ? '⚠'
196	        : '•';
197	      const meta = s.meta ? ` (${s.meta})` : '';
198	      return `${i + 1}. ${statusEmoji} [${s.kind}] ${s.label}${meta}`;
199	    }).join('\n');
200	    try {
201	      await navigator.clipboard.writeText(text);
202	      setCopied(true);
203	      setTimeout(() => setCopied(false), 1500);
204	    } catch { /* clipboard bloqueado — silencioso */ }
205	  };
206	
207	  return (
208	    <div className="rounded-xl bg-[--mia-bg-elevated]/40 backdrop-blur-md border border-[--mia-glass-border]/60 overflow-hidden transition-all duration-300 hover:bg-[--mia-bg-elevated]/50">
209	      <button
210	        onClick={() => setExpanded(!expanded)}
211	        className="w-full flex items-center gap-2 px-3 py-2 hover:bg-[--mia-bg]/40 transition-colors"
212	      >
213	        <div className="relative h-2 w-2 shrink-0">
214	          <div className={cn(
215	            'absolute inset-0 rounded-full',
216	            isRunning ? 'bg-[--mia-accent]' : 'bg-[--mia-success]',
217	          )} />
218	          {isRunning && (
219	            <div className="absolute inset-0 rounded-full bg-[--mia-accent] animate-ping opacity-75" />
220	          )}
221	        </div>
222	        <span className="text-[11px] font-semibold uppercase tracking-wider text-[--mia-text-secondary] flex-1 text-left">
223	          {isRunning ? 'MIA atuando' : `${allSteps.length} passo${allSteps.length === 1 ? '' : 's'}`}
224	        </span>
225	        <span className="text-[10px] text-[--mia-text-muted] tabular-nums">{allSteps.length}</span>
226	        <ChevronDown className={cn(
227	          'h-3.5 w-3.5 text-[--mia-text-muted] transition-transform',
228	          expanded && 'rotate-180',
229	        )} />
230	      </button>
231	
232	      {expanded && (
233	        <div className="px-3 pb-3 pt-1 max-h-[320px] overflow-y-auto animate-in fade-in duration-300">
234	          {allowCopy && (
235	            <div className="flex items-center justify-end mb-1 -mt-1">
236	              <button
237	                onClick={handleCopy}
238	                title="Copiar passos pra clipboard"
239	                className="flex items-center gap-1 px-2 py-1 rounded-md text-[10px] font-medium text-[--mia-text-muted] hover:text-[--mia-accent] hover:bg-[--mia-bg]/60 transition-colors"
240	              >
241	                {copied ? (
242	                  <>
243	                    <Check className="h-3 w-3" />
244	                    <span>Copiado</span>
245	                  </>
246	                ) : (
247	                  <>
248	                    <Copy className="h-3 w-3" />
249	                    <span>Copiar</span>
250	                  </>
251	                )}
252	              </button>
253	            </div>
254	          )}
255	          {allSteps.slice(-30).map((step, i, arr) => (
256	            <StepRow
257	              key={step.id}
258	              step={step}
259	              isActive={i === activeIdx - (allSteps.length - arr.length)}
260	            />
261	          ))}
262	        </div>
263	      )}
264	    </div>
265	  );
266	}
