  Loader2, Zap, Copy, Check,
} from 'lucide-react';
import { cn } from '@/shared/lib/utils';
import type { MiaAgentRound, MiaExecutionStep, MiaWatchLogEntry } from '@/types/mia';

export interface UnifiedStep {
  id: string;
  kind: 'think' | 'tool' | 'dom' | 'exec';
  label: string;
  status: 'pending' | 'running' | 'success' | 'error' | 'info' | 'warning';
  meta?: string;
}

function iconForStep(step: UnifiedStep) {
  if (step.kind === 'think') return Brain;
  if (step.kind === 'dom') {
    const m = step.label.toLowerCase();
    if (m.includes('clicando') || m.includes('clicado')) return MousePointer2;
    if (m.includes('preenchendo') || m.includes('preenchido')) return Type;
    if (m.includes('selecionando') || m.includes('selecionado')) return ChevronsDown;
    if (m.includes('scroll')) return MoveDown;
    if (m.includes('aguardando') || m.includes('apareceu')) return Hourglass;
    if (m.includes('navegando') || m.includes('→')) return ArrowRight;
  }
  if (step.kind === 'tool') return Zap;
  return Sparkles;
}

function statusColor(status: UnifiedStep['status']) {
  switch (status) {
    case 'running': return 'text-[--mia-accent]';
    case 'success': return 'text-emerald-500';
    case 'error': return 'text-red-500';
    case 'warning': return 'text-amber-500';
    case 'info': return 'text-[--mia-text-muted]';
    default: return 'text-[--mia-text-muted]';
  }
}

function borderColor(status: UnifiedStep['status'], isActive: boolean) {
  if (isActive) return 'border-l-[--mia-accent]';
  switch (status) {
    case 'success': return 'border-l-emerald-500/30';
    case 'error': return 'border-l-red-500/50';
    case 'warning': return 'border-l-amber-500/40';
    default: return 'border-l-[--mia-glass-border]';
  }
}

function StatusDot({ status }: { status: UnifiedStep['status'] }) {
  const Icon = status === 'running' ? Loader2
    : status === 'success' ? CheckCircle2
    : status === 'error' ? AlertCircle
    : status === 'warning' ? AlertCircle
    : null;
  if (!Icon) return null;
  return (
    <div className="absolute -bottom-0.5 -right-0.5 h-3.5 w-3.5 rounded-full bg-[--mia-bg-elevated] flex items-center justify-center shadow-sm">
      <Icon className={cn('h-2 w-2', statusColor(status), status === 'running' && 'animate-spin')} />
    </div>
  );
}

function StepRow({ step, isActive }: { step: UnifiedStep; isActive: boolean }) {
  const TypeIcon = iconForStep(step);
  return (
    <div className={cn(
      'relative flex gap-3 pl-3 border-l-2 transition-colors',
      isActive ? 'border-l-[--mia-accent] border-l-[2.5px]' : borderColor(step.status, isActive),
    )}>
      <div className={cn(
        'absolute left-0 -translate-x-1/2 w-5 h-5 rounded-full flex items-center justify-center',
        'bg-[--mia-bg-elevated] border border-[--mia-glass-border]',
      )} style={{ top: '8px' }}>
        <TypeIcon className={cn('h-3 w-3', statusColor(step.status))} />
        <StatusDot status={step.status} />
      </div>
      <div className="flex-1 py-1.5 pr-2 min-w-0">
        <div className="flex items-center gap-2">
          <span className="text-[11px] text-[--mia-text-primary] flex-1 truncate leading-snug">
            {step.label}
          </span>
          {step.meta && (
            <span className="text-[10px] text-[--mia-text-muted] tabular-nums shrink-0">
              {step.meta}
            </span>
          )}
        </div>
      </div>
    </div>
  );
}

interface MiaStepsTimelineProps {
  thinkingBlocks?: { round: number; content: string; durationMs: number }[];
  agentRounds?: MiaAgentRound[];
  executionSteps?: MiaExecutionStep[];
  watchLog?: MiaWatchLogEntry[];
  /** true durante stream live; false quando snapshot persistente */
  isStreaming?: boolean;
  /** Default expand state. Live: true. Snapshot: false (collapsed). */
  defaultExpanded?: boolean;
  /** Mostra botão "Copiar" no header (snapshot persistente). */
  allowCopy?: boolean;
}

export function MiaStepsTimeline({
  thinkingBlocks = [],
  agentRounds = [],
  executionSteps = [],
  watchLog = [],
  isStreaming = false,
  defaultExpanded,
  allowCopy = false,
}: MiaStepsTimelineProps) {
  const [expanded, setExpanded] = useState(defaultExpanded ?? isStreaming);
  const [copied, setCopied] = useState(false);

  const allSteps: UnifiedStep[] = useMemo(() => {
    const steps: UnifiedStep[] = [];
    agentRounds.forEach((round) => {
      const think = thinkingBlocks.find(t => t.round === round.round);
      if (think) {
        steps.push({
          id: `think-${round.round}`,
          kind: 'think',
          label: `Raciocínio (round ${round.round})`,
          status: round.state === 'completed' ? 'success' : round.state === 'error' ? 'error' : 'running',
          meta: `${(think.durationMs / 1000).toFixed(1)}s`,
        });
      }
      round.tools.forEach((tool, ti) => {
        steps.push({
          id: `tool-${round.round}-${ti}`,
          kind: 'tool',
          label: (tool.name || 'ferramenta').replace(/_/g, ' '),
          status: tool.status === 'running' ? 'running'
            : tool.status === 'success' || tool.success === true ? 'success'
            : tool.status === 'error' || tool.success === false ? 'error'
            : 'info',
        });
      });
    });
    executionSteps.forEach((step, i) => {
      steps.push({
        id: `exec-${i}`,
        kind: 'exec',
        label: step.label,
        status: step.status === 'running' ? 'running'
          : step.status === 'success' ? 'success'
          : step.status === 'error' ? 'error'
          : 'info',
      });
    });
    watchLog.forEach((entry) => {
      steps.push({
        id: entry.id,
        kind: 'dom',
        label: entry.message,
        status: entry.status === 'in_progress' ? 'running'
          : entry.status === 'success' ? 'success'
          : entry.status === 'error' ? 'error'
          : entry.status === 'warning' ? 'warning'
          : 'info',
      });
    });
    return steps;
  }, [thinkingBlocks, agentRounds, executionSteps, watchLog]);

  if (allSteps.length === 0) return null;

  const isRunning = allSteps.some(s => s.status === 'running');
  const activeIdx = allSteps.map(s => s.status).lastIndexOf('running');

  const handleCopy = async (e: React.MouseEvent) => {
    e.stopPropagation(); // não toggle expanded
    const text = allSteps.map((s, i) => {
      const statusEmoji = s.status === 'success' ? '✓'
        : s.status === 'error' ? '✗'
        : s.status === 'running' ? '⏳'
        : s.status === 'warning' ? '⚠'
        : '•';
      const meta = s.meta ? ` (${s.meta})` : '';
      return `${i + 1}. ${statusEmoji} [${s.kind}] ${s.label}${meta}`;
    }).join('\n');
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    } catch { /* clipboard bloqueado — silencioso */ }
  };

  return (
    <div className="rounded-xl bg-[--mia-bg-elevated]/40 backdrop-blur-md border border-[--mia-glass-border]/60 overflow-hidden transition-all duration-300 hover:bg-[--mia-bg-elevated]/50">
      <button
        onClick={() => setExpanded(!expanded)}
        className="w-full flex items-center gap-2 px-3 py-2 hover:bg-[--mia-bg]/40 transition-colors"
      >
        <div className="relative h-2 w-2 shrink-0">
          <div className={cn(
            'absolute inset-0 rounded-full',
            isRunning ? 'bg-[--mia-accent]' : 'bg-[--mia-success]',
          )} />
          {isRunning && (
            <div className="absolute inset-0 rounded-full bg-[--mia-accent] animate-ping opacity-75" />
          )}
        </div>
        <span className="text-[11px] font-semibold uppercase tracking-wider text-[--mia-text-secondary] flex-1 text-left">
          {isRunning ? 'MIA atuando' : `${allSteps.length} passo${allSteps.length === 1 ? '' : 's'}`}
        </span>
        <span className="text-[10px] text-[--mia-text-muted] tabular-nums">{allSteps.length}</span>
        <ChevronDown className={cn(
          'h-3.5 w-3.5 text-[--mia-text-muted] transition-transform',
          expanded && 'rotate-180',
        )} />
      </button>

      {expanded && (
        <div className="px-3 pb-3 pt-1 max-h-[320px] overflow-y-auto animate-in fade-in duration-300">
          {allowCopy && (
            <div className="flex items-center justify-end mb-1 -mt-1">
              <button
                onClick={handleCopy}
                title="Copiar passos pra clipboard"
                className="flex items-center gap-1 px-2 py-1 rounded-md text-[10px] font-medium text-[--mia-text-muted] hover:text-[--mia-accent] hover:bg-[--mia-bg]/60 transition-colors"
              >
                {copied ? (
                  <>
                    <Check className="h-3 w-3" />
                    <span>Copiado</span>
                  </>
                ) : (
                  <>
                    <Copy className="h-3 w-3" />
                    <span>Copiar</span>
                  </>
                )}
              </button>
            </div>
          )}
          {allSteps.slice(-30).map((step, i, arr) => (
            <StepRow
              key={step.id}
              step={step}
              isActive={i === activeIdx - (allSteps.length - arr.length)}
            />
          ))}
        </div>
      )}
    </div>
  );
}

