      <div className="h-3 w-[60%] rounded-full bg-[--mia-thinking-border] animate-[mia-shimmer_2s_ease-in-out_infinite_0.3s] bg-[length:200%_100%]"
        style={{ backgroundImage: 'linear-gradient(90deg, var(--mia-thinking-border) 0%, var(--mia-accent-subtle) 50%, var(--mia-thinking-border) 100%)' }} />
      <div className="h-3 w-[75%] rounded-full bg-[--mia-thinking-border] animate-[mia-shimmer_2s_ease-in-out_infinite_0.6s] bg-[length:200%_100%]"
        style={{ backgroundImage: 'linear-gradient(90deg, var(--mia-thinking-border) 0%, var(--mia-accent-subtle) 50%, var(--mia-thinking-border) 100%)' }} />
    </div>
  );
}

/**
 * ThinkingContent — Exibe o conteúdo do raciocínio com efeito typewriter
 */
function ThinkingContent({ content }: { content: string }) {
  const { displayed, isTyping } = useTypewriter(content, 12);

  return (
    <div className="mt-2">
      <p className="text-[13px] leading-relaxed text-[--mia-text-secondary] italic whitespace-pre-wrap">
        {displayed}
        {isTyping && <span className="mia-cursor" />}
      </p>
    </div>
  );
}

/**
 * ToolCallBadges — Badges das ferramentas usadas no round
 */
function ToolCallBadges({ tools }: { tools: MiaToolStatus[] }) {
  return (
    <div className="flex flex-wrap gap-1.5 mt-2">
      {tools.map((tool, i) => (
        <motion.span
          key={`${tool.name}-${i}`}
          initial={{ opacity: 0, scale: 0.8, y: 5 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          transition={{ delay: i * 0.1, type: 'spring', stiffness: 400 }}
          className={cn(
            "inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full text-[10px] font-semibold border transition-all",
            tool.status === 'running' && "bg-[--mia-accent-subtle] text-[--mia-accent] border-[--mia-accent]/20",
            tool.status === 'success' && "bg-[--mia-success-subtle] text-[--mia-success] border-[--mia-success]/20",
            tool.status === 'error'   && "bg-destructive/5 text-destructive border-destructive/20",
            !tool.status              && "bg-[--mia-accent-subtle] text-[--mia-accent] border-[--mia-accent]/20",
          )}
        >
          {tool.status === 'running' ? (
            <Loader2 className="h-2.5 w-2.5 animate-spin" />
          ) : tool.status === 'success' || (tool.status === undefined && tool.success === true) ? (
            <CheckCircle2 className="h-2.5 w-2.5" />
          ) : tool.status === 'error' || (tool.status === undefined && tool.success === false) ? (
            <XCircle className="h-2.5 w-2.5" />
          ) : (
            <Zap className="h-2.5 w-2.5" />
          )}
          {(typeof tool.name === 'string' ? tool.name : String(tool.name ?? 'tool')).replace(/_/g, ' ')}
        </motion.span>
      ))}
    </div>
  );
}

export function MiaThinkingBlock({ thinkingBlocks, agentRounds, isStreaming }: MiaThinkingBlockProps) {
  const [isExpanded, setIsExpanded] = useState(true);
  const [expandedRounds, setExpandedRounds] = useState<Set<number>>(new Set([1]));
  const [elapsedMs, setElapsedMs] = useState(0);

  // Live timer for active streaming
  useEffect(() => {
    let interval: NodeJS.Timeout;
    if (isStreaming) {
      interval = setInterval(() => {
        setElapsedMs(prev => prev + 100);
      }, 100);
    }
    return () => clearInterval(interval);
  }, [isStreaming]);

  // Auto-colapsa rounds concluídos quando um novo round começa
  useEffect(() => {
    if (agentRounds.length > 0) {
      const latestRound = agentRounds[agentRounds.length - 1].round;
      setExpandedRounds(prev => {
        const next = new Set(prev);
        next.add(latestRound);
        return next;
      });
    }
  }, [agentRounds.length]);

  const toggleRound = (round: number) => {
    setExpandedRounds(prev => {
      const next = new Set(prev);
      if (next.has(round)) next.delete(round);
      else next.add(round);
      return next;
    });
  };

  const isActive = isStreaming && agentRounds.some(r => r.state !== 'completed');
  const calculatedDuration = thinkingBlocks.reduce((sum, b) => sum + b.durationMs, 0);
  const totalDuration = isStreaming ? Math.max(elapsedMs, calculatedDuration) : calculatedDuration;

  const totalTools = agentRounds.flatMap(r => r.tools).length;

  const displayRounds = agentRounds.length > 0 
    ? agentRounds 
    : thinkingBlocks.map(tb => ({
        round: tb.round, 
        state: 'completed' as const, 
        tools: []
      }));

  if (displayRounds.length === 0 && !isStreaming) return null;

  return (
    <div className="ml-[38px] mb-4 max-w-[95%] sm:max-w-[90%]">
      <div className={cn(
        "transition-all duration-500 shadow-sm",
        isActive ? "mia-thinking-active" : "mia-thinking-done"
      )}>
        <div className="mia-thinking-inner">
          {/* Header Principal */}
          <button 
            onClick={() => !isActive && setIsExpanded(!isExpanded)}
            disabled={isActive}
            className={cn(
              "flex items-center justify-between w-full py-0.5 group",
              !isActive && "cursor-pointer"
            )}
          >
            <div className="flex items-center gap-2.5 flex-1 min-w-0">
              <div className="h-5 w-5 rounded-md bg-[--mia-accent-subtle] flex items-center justify-center shrink-0">
                {isActive ? (
                  <Sparkles className="h-3 w-3 text-[--mia-accent] animate-pulse" />
                ) : (
                  <Brain className="h-3 w-3 text-[--mia-text-secondary]" />
                )}
              </div>

              <div className="flex items-center gap-2 flex-1 min-w-0">
                <span className={cn(
                  "text-[11px] font-bold uppercase tracking-widest truncate",
                  isActive ? "mia-shimmer-text" : "text-[--mia-text-secondary]"
                )}>
                  {isActive ? (
                    'MIA está raciocinando...'
                  ) : (
                    <>
                      Pensou por {(totalDuration / 1000).toFixed(1)}s
                      <span className="mx-1.5 opacity-30">·</span>
                      {agentRounds.length} round{agentRounds.length > 1 ? 's' : ''}
                      <span className="mx-1.5 opacity-30">·</span>
                      {totalTools} tool{totalTools !== 1 ? 's' : ''}
                    </>
                  )}
                </span>
              </div>
            </div>

            {!isActive && (
              <ChevronDown className={cn(
                "h-3.5 w-3.5 text-[--mia-text-muted] transition-transform duration-300",
                isExpanded && "rotate-180"
              )} />
            )}
          </button>

          {/* Conteúdo Expansível */}
          <AnimatePresence initial={false}>
            {(isExpanded || isActive) && (
              <motion.div
                variants={miaMotion.thinkingExpand}
                initial="initial"
                animate="animate"
                exit="exit"
                className="overflow-hidden"
              >
                {displayRounds.map((round, idx) => {
                  const thinking = thinkingBlocks.find(b => b.round === round.round);
                  const isRoundExpanded = expandedRounds.has(round.round) || round.state !== 'completed';

                  return (
                    <div key={round.round} className={cn(
                      "mt-3 pt-3 border-t border-[--mia-thinking-border]/50",
                      idx === 0 && "mt-2"
                    )}>
                      {/* Sub-Header de Round */}
                      <button 
                        onClick={() => toggleRound(round.round)}
                        className="flex items-center justify-between w-full mb-1"
                      >
                        <div className="flex items-center gap-2">
                          <span className="text-[10px] font-bold text-[--mia-text-muted] uppercase tracking-tighter bg-stone-100 dark:bg-stone-800 px-1.5 py-0.5 rounded">
                            R{round.round}
                          </span>
                          <span className="text-[12px] font-semibold text-[--mia-text-secondary]">
                            {thinking 
                              ? `Reasoning (${(((isStreaming && round.state !== 'completed') ? Math.max(elapsedMs, thinking.durationMs) : thinking.durationMs) / 1000).toFixed(1)}s)` 
                              : 'Processando...'}
                          </span>
                        </div>
                        <ChevronDown className={cn(
                          "h-3 w-3 text-[--mia-text-muted] transition-transform",
                          isRoundExpanded && "rotate-180"
                        )} />
                      </button>

                      {/* Conteúdo do Round */}
                      <AnimatePresence initial={false}>
                        {isRoundExpanded && (
                          <motion.div
                            variants={miaMotion.thinkingExpand}
                            initial="initial"
                            animate="animate"
                            exit="exit"
                            className="overflow-hidden"
                          >
                            {/* Skeleton Shimmer enquanto pensa */}
                            {round.state === 'thinking' && !thinking && (
                              <ThinkingSkeleton />
                            )}

                            {/* Conteúdo com Typewriter */}
                            {thinking && (
                              <ThinkingContent content={thinking.content} />
                            )}

                            {/* Tool Calls do Round */}
                            {round.tools.length > 0 && (
                              <ToolCallBadges tools={round.tools} />
                            )}

                            {/* Estado Reflecting */}
                            {round.state === 'reflecting' && (
                              <div className="flex items-center gap-2 mt-2 py-1 px-2 rounded-lg bg-amber-50 dark:bg-amber-950/20 text-amber-600 dark:text-amber-500 text-[11px] font-medium border border-amber-200/50 dark:border-amber-500/20">
                                <Loader2 className="h-3 w-3 animate-spin" />
                                <Sparkles className="h-2.5 w-2.5" />
                                Corrigindo erros e refletindo...
                              </div>
                            )}
                          </motion.div>
                        )}
                      </AnimatePresence>
                    </div>
                  );
                })}

                {/* Skeleton Geral se nenhum round apareceu ainda mas está streamando */}
                {isStreaming && agentRounds.length === 0 && (
                  <div className="mt-3 pt-3 border-t border-[--mia-thinking-border]/50">
                    <ThinkingSkeleton />
                  </div>
                )}
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>
    </div>
  );
}

