import React from 'react';
import { motion } from 'framer-motion';
import { 
  Sparkles, User, Copy, ThumbsUp, ThumbsDown, 
  RotateCcw, Check 
} from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { MiaChatMessage } from '@/types/mia';
import { miaMarkdownComponents } from './mia-markdown-components';
import { miaMotion } from './mia-animations';
import { MiaActionBadge } from './MiaActionBadge';
import { MiaClarificationChips } from './MiaClarificationChips';
import { cn } from '@/shared/lib/utils';
import { Button } from '@/shared/ui/button';
import { format } from 'date-fns';

interface MiaMessageBubbleProps {
  message: MiaChatMessage;
  isLast?: boolean;
  onClarificationAnswer?: (messageId: string, value: string, label: string) => void;
}

const UserAvatar = () => (
  <div className="h-8 w-8 rounded-full bg-[--mia-bg-subtle] border border-[--mia-glass-border] flex items-center justify-center text-[--mia-text-secondary] shrink-0">
    <User className="h-4.5 w-4.5" />
  </div>
);

const AssistantAvatar = () => (
  <div className="h-7 w-7 rounded-lg bg-gradient-to-br from-[--mia-accent] to-[--mia-thinking-to] flex items-center justify-center text-white shrink-0 shadow-sm shadow-[--mia-accent-glow]">
    <Sparkles className="h-4 w-4" />
  </div>
);

export function MiaMessageBubble({ message, isLast, onClarificationAnswer }: MiaMessageBubbleProps) {
  const isAssistant = message.role === 'assistant';
  const timestamp = format(message.timestamp, 'HH:mm');

  if (!isAssistant) {
    return (
      <motion.div
        variants={miaMotion.message}
        initial="initial"
        animate="animate"
        className="flex justify-end mb-6 w-full"
      >
        <div className="flex flex-col items-end max-w-[70%] sm:max-w-[85%]">
          <div className="px-4 py-3 rounded-2xl rounded-br-md bg-[--mia-accent] text-white shadow-sm shadow-[--mia-accent-glow]/20 border border-transparent">
            {/* Fonte normal sans — só a Mia tem serif sofisticado */}
            <p className="font-sans text-[15px] leading-relaxed whitespace-pre-wrap">
              {message.content}
            </p>
          </div>
          <div className="flex items-center gap-2 mt-1.5 px-1">
            <span className="text-[10px] text-[--mia-text-muted] font-medium uppercase tracking-wider">
              {timestamp}
            </span>
            <Check className="h-3 w-3 text-[--mia-accent]" />
          </div>
        </div>
      </motion.div>
    );
  }

  return (
    <motion.div
      variants={miaMotion.message}
      initial="initial"
      animate="animate"
      className="flex flex-col mb-10 w-full group"
    >
      {/* Header: Avatar + Nome */}
      <div className="flex items-center gap-3 mb-2">
        <AssistantAvatar />
        <span className="text-xs font-bold text-[--mia-text-secondary] uppercase tracking-wider">
          MIA
        </span>
      </div>

      {/* Thinking Block */}
      {(message.thinkingBlocks || message.agentRounds) && (
        <MiaThinkingBlock 
          thinkingBlocks={message.thinkingBlocks || []}
          agentRounds={message.agentRounds || []}
          isStreaming={false}
        />
      )}

      {/* Conteúdo: Flat + Serif + Indentado */}
      <div className="pl-[40px] flex flex-col">
        <div className="prose-mia max-w-none">
          <ReactMarkdown 
            remarkPlugins={[remarkGfm]} 
            components={miaMarkdownComponents}
          >
            {message.content}
          </ReactMarkdown>
        </div>

        {/* Action Badges */}
        {message.actions && message.actions.length > 0 && (
          <div className="flex flex-wrap gap-2 mt-4">
            {message.actions.map((action, idx) => (
              <MiaActionBadge
                key={idx}
                action={action}
                status={message.actionsExecuted ? 'executed' : 'pending'}
              />
            ))}
          </div>
        )}

        {/* Clarification chips (ask_clarification — espelha AskUserQuestion) */}
        {message.clarification && onClarificationAnswer && (
          <MiaClarificationChips
            clarification={message.clarification}
            onAnswer={(value, label) => onClarificationAnswer(message.id, value, label)}
          />
        )}

        {/* Steps Timeline PERSISTENTE — raciocínio + tools + DOM actions + execution steps
            que MIA fez nesta mensagem. SEMPRE renderiza quando há QUALQUER passo —
            o user pode expandir o dropdown e copiar a qualquer momento.
            Antes: somia quando clarification chegava (closure stale do useMia.ts).
            Agora: lê do snapshot persistido no MiaChatMessage. */}
        {isAssistant && (
          (message.agentRounds?.length || 0) > 0 ||
          (message.thinkingBlocks?.length || 0) > 0 ||
          (message.watchLogSnapshot?.length || 0) > 0 ||
          (message.executionStepsSnapshot?.length || 0) > 0
        ) ? (
          <div className="mt-3">
            <MiaStepsTimeline
              thinkingBlocks={message.thinkingBlocks}
              agentRounds={message.agentRounds}
              executionSteps={message.executionStepsSnapshot}
              watchLog={message.watchLogSnapshot}
              isStreaming={false}
              defaultExpanded={true}
              allowCopy
            />
          </div>
        ) : null}

        {/* Metadata & Mini Actions */}
        <div className="flex items-center gap-4 mt-4 px-1">
          <span className="text-[10px] font-medium text-[--mia-text-muted] tracking-tight uppercase">
            {timestamp}
          </span>

          <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity duration-200">
            <Button variant="ghost" size="icon" className="h-7 w-7 text-[--mia-text-muted] hover:text-[--mia-accent] rounded-lg">
              <Copy className="h-3.5 w-3.5" />
            </Button>
            <Button variant="ghost" size="icon" className="h-7 w-7 text-[--mia-text-muted] hover:text-[--mia-success] rounded-lg">
              <ThumbsUp className="h-3.5 w-3.5" />
            </Button>
            <Button variant="ghost" size="icon" className="h-7 w-7 text-[--mia-text-muted] hover:text-destructive rounded-lg">
              <ThumbsDown className="h-3.5 w-3.5" />
            </Button>
            {isLast && (
              <Button variant="ghost" size="icon" className="h-7 w-7 text-[--mia-text-muted] hover:text-[--mia-accent] rounded-lg">
                <RotateCcw className="h-3.5 w-3.5" />
              </Button>
            )}
          </div>
        </div>
      </div>
    </motion.div>
  );
}

