import React, { useRef, useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { ArrowUp, Square } from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { cn } from '@/shared/lib/utils';
import { useTextareaAutoHeight } from '../lib/useTextareaAutoHeight';

interface MiaComposerProps {
  value: string;
  onChange: (value: string) => void;
  onSend: () => void;
  onStop: () => void;
  isStreaming: boolean;
  disabled: boolean;
}

export function MiaComposer({
  value,
  onChange,
  onSend,
  onStop,
  isStreaming,
  disabled
}: MiaComposerProps) {
  const composerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const [containerWidth, setContainerWidth] = useState(0);

  useEffect(() => {
    if (composerRef.current) {
      setContainerWidth(composerRef.current.offsetWidth);
      const observer = new ResizeObserver((entries) => {
        if (entries[0]) {
          setContainerWidth(entries[0].contentRect.width);
        }
      });
      observer.observe(composerRef.current);
      return () => observer.disconnect();
    }
  }, []);

  const textareaHeight = useTextareaAutoHeight(value, containerWidth);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      if (value.trim() && !disabled && !isStreaming) {
        onSend();
      }
    }
  };

  const canSend = value.trim().length > 0 && !disabled;

  return (
    <motion.div
      ref={composerRef}
      className={cn(
              "relative flex items-end gap-2 p-2 rounded-3xl",
              "bg-[--mia-bg-elevated] border border-[--mia-glass-border]",
              "shadow-lg shadow-black/[0.03]",
              "backdrop-blur-sm",
              "transition-all duration-200",
              "focus-within:border-[--mia-accent]/40",
              "focus-within:shadow-[0_0_0_3px_var(--mia-accent-glow)]"
            )}
            whileTap={{ scale: 0.998 }}
          >
            {/* Textarea — native to avoid Shadcn mobile overrides */}
            <textarea
              ref={textareaRef}
              value={value}
              onChange={(e) => onChange(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="Pergunte qualquer coisa para a MIA..."
              disabled={disabled && !isStreaming}
              className="flex-1 min-h-[44px] max-h-[200px] border-0 focus-visible:ring-0 focus-visible:outline-none bg-transparent py-3 px-2 text-[15px] text-[--mia-text-primary] placeholder:text-[--mia-text-muted] resize-none font-sans"
              style={{ 
                height: textareaHeight, 
                overflowY: Number(textareaHeight) >= 190 ? 'auto' : 'hidden' 
              }}
            />

            {/* Send/Stop button */}
            <Button
              onClick={isStreaming ? onStop : onSend}
              disabled={!canSend && !isStreaming}
              size="icon"
              className={cn(
                "h-9 w-9 rounded-xl mb-0.5 mr-0.5 transition-all duration-200 shrink-0",
                isStreaming 
                  ? "bg-stone-800 hover:bg-stone-900 text-white shadow-sm"
                  : canSend
                    ? "bg-[--mia-accent] hover:bg-[--mia-accent-hover] text-white shadow-sm"
                    : "bg-stone-100 text-[--mia-text-muted]"
              )}
            >
              {isStreaming ? (
                <Square className="h-4 w-4 fill-current" />
              ) : (
                <ArrowUp className="h-4.5 w-4.5 stroke-[2.5px]" />
              )}
            </Button>
    </motion.div>
  );
}

import React, { useState } from 'react';
import { Components } from 'react-markdown';
import { Copy, Check } from 'lucide-react';
import { Button } from '@/shared/ui/button';

const CopyButton = ({ text }: { text: string }) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <Button data-mia-action="copy"
      variant="ghost"
      size="icon"
      onClick={handleCopy}
      className="absolute top-2 right-2 h-8 w-8 text-stone-400 hover:text-white hover:bg-white/10 opacity-0 group-hover:opacity-100 transition-all duration-200"
    >
      {copied ? <Check className="h-4 w-4 text-green-400" /> : <Copy className="h-4 w-4" />}
    </Button>
  );
};

export const miaMarkdownComponents: Components = {
  p: ({ children }) => (
    <p className="mb-4 last:mb-0" style={{ fontFamily: 'Georgia, Cambria, serif', fontSize: 16, lineHeight: 1.75 }}>
      {children}
    </p>
  ),

  h1: ({ children }) => (
    <h1 className="text-xl font-semibold font-momma text-[--mia-text-primary] mt-6 mb-3 tracking-tight">
      {children}
    </h1>
  ),
  h2: ({ children }) => (
    <h2 className="text-lg font-semibold font-momma text-[--mia-text-primary] mt-5 mb-2 tracking-tight">
      {children}
    </h2>
  ),
  h3: ({ children }) => (
    <h3 className="text-base font-semibold font-momma text-[--mia-text-primary] mt-4 mb-2 tracking-tight">
      {children}
    </h3>
  ),

  strong: ({ children }) => (
    <strong className="font-semibold text-[--mia-text-primary]">
      {children}
    </strong>
  ),

  em: ({ children }) => <em className="italic">{children}</em>,

  a: ({ href, children }) => (
    <a 
      href={href} 
      className="text-[--mia-accent] font-medium underline underline-offset-4 hover:text-[--mia-accent-hover] transition-colors" 
      target="_blank" 
      rel="noopener noreferrer"
    >
      {children}
    </a>
  ),

  ul: ({ children }) => <ul className="list-disc pl-6 mb-4 space-y-2">{children}</ul>,
  ol: ({ children }) => <ol className="list-decimal pl-6 mb-4 space-y-2">{children}</ol>,
  li: ({ children }) => (
    <li className="pl-1" style={{ fontFamily: 'Georgia, Cambria, serif', fontSize: 16, lineHeight: 1.6 }}>
      {children}
    </li>
  ),

  blockquote: ({ children }) => (
    <blockquote className="border-l-4 border-[--mia-accent] bg-[--mia-accent-subtle] px-5 py-3 rounded-r-xl mb-6 italic text-[--mia-text-secondary]">
      {children}
    </blockquote>
  ),

  code: ({ inline, className, children }) => {
    const match = /language-(\w+)/.exec(className || '');
    if (inline) {
      return (
        <code className="px-1.5 py-0.5 rounded-md bg-[--mia-accent-subtle] text-[--mia-accent-hover] text-[13px] font-mono font-medium">
          {children}
        </code>
      );
    }
    return (
      <div className="relative group mb-6">
        <pre className="bg-[hsl(60,5%,12%)] border border-[hsl(60,5%,20%)] rounded-xl p-5 overflow-x-auto shadow-inner">
          <code className="text-[13px] leading-relaxed font-mono text-[hsl(46,40%,90%)]">
            {children}
          </code>
        </pre>
        <CopyButton text={String(children)} />
        {match && (
          <span className="absolute bottom-2 right-4 text-[10px] text-stone-500 uppercase font-mono tracking-widest pointer-events-none">
            {match[1]}
          </span>
        )}
      </div>
    );
  },

  table: ({ children }) => (
    <div className="overflow-x-auto mb-6 rounded-xl border border-[--mia-glass-border] shadow-sm bg-[--mia-bg-elevated]">
      <table className="w-full text-sm border-collapse">{children}</table>
    </div>
  ),

  thead: ({ children }) => <thead className="bg-[--mia-accent-subtle]">{children}</thead>,

  th: ({ children }) => (
    <th className="px-4 py-3 text-left text-[11px] uppercase tracking-wider font-bold font-momma text-[--mia-text-secondary] border-b border-[--mia-glass-border]">
      {children}
    </th>
  ),

  td: ({ children }) => (
    <td 
      className="px-4 py-3 border-t border-[--mia-glass-border] text-[14px]" 
      style={{ fontFamily: 'Georgia, serif' }}
    >
      {children}
    </td>
  ),
};

