import { motion } from 'framer-motion';
import {
  Wand2,
  Zap,
  Brain,
  Package,
  ClipboardList,
  ArrowRight,
  Sparkles,
  Repeat2,
} from 'lucide-react';
import { useMemo, useEffect, useState } from 'react';
import { miaMotion } from './mia-animations';
import { useAuth } from '@/shared/hooks/useAuth';
import { usePermissions } from '@/shared/hooks/usePermissions';
import { supabase } from '@/integrations/supabase/client';

interface MiaWelcomeProps {
  onSelectSuggestion: (prompt: string) => void;
}

const SUGGESTIONS = [
  {
    label: 'Vendas do Dia',
    description: 'Faturamento detalhado por loja',
    icon: Zap,
    prompt: 'Qual foi o faturamento de hoje em cada loja?',
  },
  {
    label: 'Estoque Atual',
    description: 'Produtos com baixo estoque ou zerados',
    icon: Package,
    prompt: 'Quais produtos estão com estoque baixo ou zerado agora?',
  },
  {
    label: 'Produção do Dia',
    description: 'O que foi produzido hoje',
    icon: ClipboardList,
    prompt: 'Me mostre o resumo da produção de hoje.',
  },
  {
    label: 'Análise Inteligente',
    description: 'Insights e recomendações de negócio',
    icon: Brain,
    prompt: 'Quais insights você tem sobre o desempenho recente da Momma?',
  },
];

/**
 * Mensagens de boas-vindas adaptativas por role — cada role tem tom e foco
 * diferentes refletindo o dia-a-dia real.
 */
type RoleWelcome = {
  headline: (firstName: string) => string;
  description: string;
};

const WELCOME_BY_ROLE: Record<string, RoleWelcome> = {
  admin: {
    headline: (name) => `Olá ${name}, eu sou a Mia`,
    description:
      'Sua assistente inteligente da Momma. Tenho acesso total ao sistema — finanças, produção, estoque, logística, relatórios executivos e auditoria. É só perguntar.',
  },
  gerente: {
    headline: (name) => `Oi ${name}, no que posso ajudar?`,
    description:
      'Sou a Mia, sua co-piloto de gestão. Posso te ajudar com fechamentos, performance da loja, metas de vendas, acompanhamento de equipe e relatórios operacionais.',
  },
  operacoes: {
    headline: (name) => `Bem-vindo(a), ${name}`,
    description:
      'Eu sou a Mia. Posso te ajudar com requisições, conferências de estoque, conferências de produção, encomendas do dia e lançamentos rápidos. Me pergunte qualquer coisa da operação.',
  },
  financeiro: {
    headline: (name) => `Oi ${name}, bora cuidar do caixa?`,
    description:
      'Eu sou a Mia. Posso te apoiar com DRE, contas a pagar/receber, conciliação bancária, notas fiscais e fechamento do cofre.',
  },
  producao: {
    headline: (name) => `E aí, ${name}?`,
    description:
      'Sou a Mia, sua assistente de produção. Posso te ajudar com programação diária, fichas técnicas, perdas, rendimento por produto e controle de lotes.',
  },
  vendedor: {
    headline: (name) => `Olá ${name} 👋`,
    description:
      'Sou a Mia. Me pergunte sobre encomendas do dia, estoque disponível, preços de produtos e atendimento de clientes. Tô aqui pra agilizar seu dia.',
  },
  default: {
    headline: (name) => `Olá ${name}, eu sou a Mia`,
    description:
      'Sua assistente inteligente da Momma. Pergunte sobre finanças, produção, estoque ou qualquer dado do seu negócio.',
  },
};

function resolveWelcomeByRole(roleName: string | undefined): RoleWelcome {
  if (!roleName) return WELCOME_BY_ROLE.default;
  const normalized = roleName.toLowerCase().trim();
  if (['admin', 'administrador', 'administrator'].includes(normalized)) {
    return WELCOME_BY_ROLE.admin;
  }
  if (['gerente', 'manager', 'gerencia'].includes(normalized)) {
    return WELCOME_BY_ROLE.gerente;
  }
  if (
    ['operacoes', 'operações', 'operações gerais', 'operacional'].includes(
      normalized,
    )
  ) {
    return WELCOME_BY_ROLE.operacoes;
  }
  if (['financeiro', 'finance', 'contador'].includes(normalized)) {
    return WELCOME_BY_ROLE.financeiro;
  }
  if (['producao', 'produção', 'chef', 'confeiteiro'].includes(normalized)) {
    return WELCOME_BY_ROLE.producao;
  }
  if (
    ['vendedor', 'vendedora', 'atendente', 'atendimento', 'caixa'].includes(
      normalized,
    )
  ) {
    return WELCOME_BY_ROLE.vendedor;
  }
  return WELCOME_BY_ROLE.default;
}

interface WorkflowChip {
  id: string;
  name: string;
  useCount: number;
  pagePath: string | null;
}

export function MiaWelcome({ onSelectSuggestion }: MiaWelcomeProps) {
  const { userProfile } = useAuth();
  const { userRole } = usePermissions();
  const [workflows, setWorkflows] = useState<WorkflowChip[]>([]);

  // Carrega top 4 workflows do user — usados >= 2 vezes, aceitos.
  // Chip 1-click = re-executar workflow direto, sem LLM round trip.
  useEffect(() => {
    void (async () => {
      try {
        const { data: { user } } = await supabase.auth.getUser();
        if (!user) return;
        const { data } = await supabase
          .from('mia_user_workflows')
          .select('id, name, use_count, page_path')
          .eq('user_id', user.id)
          .eq('proposal_status', 'accepted')
          .gte('use_count', 2)
          .order('use_count', { ascending: false })
          .order('last_used_at', { ascending: false })
          .limit(4);
        if (data && data.length > 0) {
          setWorkflows(data.map((w: any) => ({
            id: w.id,
            name: w.name,
            useCount: w.use_count ?? 0,
            pagePath: w.page_path,
          })));
        }
      } catch { /* silent */ }
    })();
  }, []);

  const firstName = useMemo(() => {
    return (userProfile?.nome || 'parceiro').split(' ')[0];
  }, [userProfile]);

  const welcome = useMemo(
    () => resolveWelcomeByRole(userRole?.role_name),
    [userRole],
  );

  return (
    <motion.div
      variants={miaMotion.welcome}
      initial="initial"
      animate="animate"
      className="flex flex-col items-center justify-center text-center px-4 py-6 h-full"
    >
      {/* Avatar Mia — varinha mágica coral, pulso suave */}
      <div className="relative mb-4 md:mb-5">
        <motion.div
          animate={{ scale: [1, 1.02, 1] }}
          transition={{
            duration: 5,
            repeat: Infinity,
            ease: 'easeInOut',
          }}
          className="relative h-14 w-14 md:h-16 md:w-16 rounded-[22px] bg-gradient-to-br from-[--mia-accent] via-[--mia-accent] to-[--mia-thinking-to] flex items-center justify-center shadow-[0_8px_30px_var(--mia-accent-glow)] z-10"
        >
          <Wand2 className="h-6 w-6 md:h-7 md:w-7 text-white drop-shadow-sm" strokeWidth={1.6} />
        </motion.div>
        {/* Glow ring animado */}
        <div className="absolute inset-0 rounded-[22px] bg-gradient-to-br from-[--mia-accent] to-[--mia-thinking-to] opacity-25 blur-2xl animate-pulse" />
      </div>

      {/* Título: serif sofisticado + cor do tema */}
      <h1 className="text-2xl md:text-3xl font-serif font-medium text-[--mia-text-primary] leading-tight tracking-tight">
        {welcome.headline(firstName)}
      </h1>
      <p className="font-serif text-[--mia-text-secondary] max-w-lg mt-2 text-sm md:text-[15px] leading-relaxed">
        {welcome.description}
      </p>

      {/* Workflows recorrentes do user — atalhos clicáveis sem LLM round-trip */}
      {workflows.length > 0 && (
        <div className="w-full max-w-2xl mt-6 md:mt-8">
          <div className="flex items-center gap-2 mb-2 text-[11px] uppercase tracking-wide text-[--mia-text-muted] font-semibold">
            <Repeat2 className="h-3.5 w-3.5" />
            Atalhos seus
          </div>
          <div className="flex flex-wrap gap-2">
            {workflows.map((w) => (
              <button
                key={w.id}
                onClick={() => onSelectSuggestion(`executar workflow: ${w.name}`)}
                className="group flex items-center gap-2 px-3 py-1.5 rounded-full bg-[--mia-accent-subtle] border border-[--mia-accent]/20 hover:bg-[--mia-accent]/15 transition-all text-xs"
                title={w.pagePath ? `Rota: ${w.pagePath}` : undefined}
              >
                <Sparkles className="h-3 w-3 text-[--mia-accent]" />
                <span className="text-[--mia-text-primary] font-medium">{w.name}</span>
                <span className="text-[10px] text-[--mia-text-muted] tabular-nums">{w.useCount}×</span>
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Suggestion Chips — Grid 2x2 compacto */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5 w-full max-w-2xl mt-6 md:mt-8">
        {SUGGESTIONS.map((s, i) => (
          <motion.button
            key={s.label}
            variants={miaMotion.chip(i)}
            initial="initial"
            animate="animate"
            whileHover={{
              y: -3,
              boxShadow: '0 10px 25px var(--mia-accent-glow)',
            }}
            whileTap={{ scale: 0.98 }}
            onClick={() => onSelectSuggestion(s.prompt)}
            className="flex items-center gap-3 p-3 rounded-xl bg-[--mia-bg-elevated] border border-[--mia-glass-border] hover:border-[--mia-accent]/40 transition-all text-left group shadow-sm"
          >
            <div className="h-10 w-10 rounded-lg bg-[--mia-accent-subtle] flex items-center justify-center group-hover:bg-[--mia-accent]/15 transition-colors shrink-0">
