import React from 'react';
import { motion } from 'framer-motion';
import { Sparkles, User, Copy, Check } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { useState, useCallback } from 'react';
import { MiaChatMessage } from '@/types/mia';
import { miaMarkdownComponents } from './mia-markdown-components';
import { miaMotion } from './mia-animations';
import { MiaActionBadge } from './MiaActionBadge';
import { MiaClarificationChips } from './MiaClarificationChips';
import { cn } from '@/shared/lib/utils';
import { format } from 'date-fns';

interface MiaMessageBubbleProps {
  message: MiaChatMessage;
  isLast?: boolean;
  onClarificationAnswer?: (messageId: string, value: string, label: string) => void;
}

function CopyText({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);
  const handle = useCallback(async () => {
    await navigator.clipboard.writeText(text).catch(() => {});
    setCopied(true);
    setTimeout(() => setCopied(false), 1500);
  }, [text]);
  return (
    <button
      onClick={handle}
      className="flex items-center gap-1 px-2 py-1 rounded-md text-[11px] text-[--mia-text-muted] hover:text-[--mia-accent] transition-colors"
      title="Copiar resposta"
    >
      {copied ? <Check className="h-3 w-3" /> : <Copy className="h-3 w-3" />}
      <span>{copied ? 'Copiado' : 'Copiar'}</span>
    </button>
  );
}

export function MiaMessageBubble({ message, onClarificationAnswer }: MiaMessageBubbleProps) {
  const isAssistant = message.role === 'assistant';
  const timestamp = format(message.timestamp, 'HH:mm');

  /* ── Mensagem do usuário ── */
  if (!isAssistant) {
    return (
      <motion.div
        variants={miaMotion.message}
        initial="initial"
        animate="animate"
        className="flex justify-end mb-5"
      >
        <div className="flex flex-col items-end gap-1 max-w-[72%] sm:max-w-[80%]">
          <div className="px-4 py-2.5 rounded-2xl rounded-br-sm bg-[--mia-accent] text-white shadow-sm">
            <p className="text-[15px] leading-relaxed whitespace-pre-wrap font-sans">{message.content}</p>
          </div>
          <div className="flex items-center gap-1.5 px-1">
            <span className="text-[10px] text-[--mia-text-muted]">{timestamp}</span>
            <Check className="h-3 w-3 text-[--mia-accent]/70" />
          </div>
        </div>
        <div className="h-7 w-7 rounded-full bg-[--mia-glass-border]/60 border border-[--mia-glass-border] flex items-center justify-center ml-2.5 mt-0.5 shrink-0">
          <User className="h-3.5 w-3.5 text-[--mia-text-muted]" />
        </div>
      </motion.div>
    );
  }

  /* ── Resposta da MIA ── */
  return (
    <motion.div
      variants={miaMotion.message}
      initial="initial"
      animate="animate"
      className="flex gap-3 mb-8 group"
    >
      {/* Avatar */}
      <div className="h-7 w-7 rounded-lg bg-gradient-to-br from-[--mia-accent] to-[--mia-thinking-to] flex items-center justify-center shrink-0 mt-0.5 shadow-sm shadow-[--mia-accent-glow]">
        <Sparkles className="h-3.5 w-3.5 text-white" />
      </div>

      <div className="flex-1 min-w-0">
        {/* Texto (sem card/borda) */}
        <div className="prose-mia max-w-none">
          <ReactMarkdown remarkPlugins={[remarkGfm]} components={miaMarkdownComponents}>
            {message.content}
          </ReactMarkdown>
        </div>

        {/* Action badges — só quando MIA executou navegação/ação */}
        {message.actions && message.actions.length > 0 && (
          <div className="flex flex-wrap gap-1.5 mt-3">
            {message.actions.map((action, idx) => (
              <MiaActionBadge key={idx} action={action} status={message.actionsExecuted ? 'executed' : 'pending'} />
            ))}
          </div>
        )}

        {/* Clarification chips */}
        {message.clarification && onClarificationAnswer && (
          <MiaClarificationChips
            clarification={message.clarification}
            onAnswer={(value, label) => onClarificationAnswer(message.id, value, label)}
          />
        )}

        {/* Meta row — timestamp + copiar, visível só no hover */}
        <div className={cn(
          'flex items-center gap-2 mt-2 transition-opacity duration-200',
          'opacity-0 group-hover:opacity-100',
        )}>
          <span className="text-[10px] text-[--mia-text-muted] px-0.5">{timestamp}</span>
          <CopyText text={message.content} />
        </div>
      </div>
    </motion.div>
  );
}

