import { MiaChatMessage } from '@/types/mia';
import { miaMarkdownComponents } from './mia-markdown-components';
import { miaMotion } from './mia-animations';
import { MiaActionBadge } from './MiaActionBadge';
import { MiaClarificationChips } from './MiaClarificationChips';
import { format } from 'date-fns';

interface MiaMessageBubbleProps {
  message: MiaChatMessage;
  isLast?: boolean;
  onClarificationAnswer?: (messageId: string, value: string, label: string) => void;
}

const UserAvatar = () => (
  <div className="h-8 w-8 rounded-full bg-[--mia-bg-subtle] border border-[--mia-glass-border] flex items-center justify-center text-[--mia-text-secondary] shrink-0">
    <User className="h-4.5 w-4.5" />
  </div>
);

const AssistantAvatar = () => (
  <div className="h-7 w-7 rounded-lg bg-gradient-to-br from-[--mia-accent] to-[--mia-thinking-to] flex items-center justify-center text-white shrink-0 shadow-sm shadow-[--mia-accent-glow]">
