);

export function MiaMessageBubble({ message, isLast, onClarificationAnswer }: MiaMessageBubbleProps) {
  const isAssistant = message.role === 'assistant';
  const timestamp = format(message.timestamp, 'HH:mm');

  if (!isAssistant) {
    return (
      <motion.div
        variants={miaMotion.message}
        initial="initial"
        animate="animate"
        className="flex justify-end mb-6 w-full"
