import { useState, useCallback, useMemo } from 'react';
import { useMia } from '@/shared/contexts/MiaContext';
import {
  MiaChatHeader,
  MiaMessageList,
  MiaWelcome,
  MiaComposer
} from './';
import { Sparkles, Brain } from 'lucide-react';
import { cn } from '@/shared/lib/utils';
import '../styles/mia-chat.css';

export default function MiaPage() {
  const {
    messages,
    sendMessage,
    isStreaming,
    conversations,
    activeConversationId,
    startNewConversation,
    executionSteps,
    abortStream,
    streamingText,
    streamingStatus,
    thinkingBlocks,
    agentRounds,
    activeTaskPlan,
    approveTaskPlan,
    cancelTaskPlan,
    answerClarification,
    pendingConfirmation,
    confirmPendingActions,
    cancelPendingActions,
    rawMode,
    setRawMode,
    rawModeOptions,
    setRawModeOptions,
  } = useMia();

  const [input, setInput] = useState('');

  const activeConversation = useMemo(() =>
    conversations.find(c => c.id === activeConversationId),
    [conversations, activeConversationId]
  );

  const handleSend = useCallback(() => {
    const text = input.trim();
    if (!text || isStreaming) return;
    setInput('');
    sendMessage(text);
  }, [input, isStreaming, sendMessage]);

  const handleSuggestion = useCallback((prompt: string) => {
    setInput('');
    sendMessage(prompt);
  }, [sendMessage]);

  return (
    <div className="flex h-[100dvh] w-full overflow-hidden bg-[--mia-bg] font-momma">
      {/* Main Chat Area */}
      <main className="flex-1 flex flex-col relative min-w-0 bg-[--mia-bg]">
        {/* Header (Responsive) */}
        <MiaChatHeader
          conversationTitle={activeConversation?.title}
          onNewConversation={startNewConversation}
        />

        {/* Messages / Welcome View */}
        <MiaMessageList
          messages={messages}
          isStreaming={isStreaming}
          streamingText={streamingText}
          streamingStatus={streamingStatus}
          thinkingBlocks={thinkingBlocks}
          agentRounds={agentRounds}
          executionSteps={executionSteps}
          activeTaskPlan={activeTaskPlan}
          pendingConfirmation={pendingConfirmation}
          onConfirm={confirmPendingActions}
          onCancelConfirm={cancelPendingActions}
          onApproveTask={approveTaskPlan}
          onCancelTask={cancelTaskPlan}
          onClarificationAnswer={answerClarification}
          emptyState={<MiaWelcome onSelectSuggestion={handleSuggestion} />}
        />

        {/* ── Bottom: Controls + Composer ── */}
        <div className="sticky bottom-0 left-0 right-0 z-10">
          <div className="h-12 bg-gradient-to-t from-[--mia-bg] via-[--mia-bg-overlay] to-transparent pointer-events-none" />

          <div className="bg-[--mia-bg] px-2 sm:px-4 pb-2 sm:pb-4 pt-0">
            <div className="max-w-3xl mx-auto">
              {/* Mode controls — above composer, tight and scrollable */}
              <div className="flex items-center gap-2 mb-2 px-2 overflow-x-auto scrollbar-hide">
                <button
                  onClick={() => setRawMode(!rawMode)}
                  className={cn(
                    "inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[11px] font-medium transition-all duration-200 border whitespace-nowrap select-none",
                    !rawMode
                      ? "bg-[--mia-accent] border-[--mia-accent] text-white"
                      : "bg-transparent border-[--mia-glass-border] text-[--mia-text-muted] hover:border-[--mia-accent]/30 hover:text-[--mia-text-secondary]"
                  )}
                  title={rawMode ? 'Ativar MIA (assistente Momma com dados internos)' : 'Desativar MIA (chat livre)'}
                >
                  <Sparkles className="h-3 w-3" />
                  {rawMode ? 'MIA off' : 'MIA v2'}
                </button>

                {rawMode && (
                  <button
                    onClick={() => setRawModeOptions({ reasoning: !rawModeOptions.reasoning })}
                    className={cn(
                      "inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[11px] font-medium transition-all duration-200 border whitespace-nowrap select-none",
                      rawModeOptions.reasoning
                        ? "bg-violet-500/10 border-violet-500/30 text-violet-600 dark:text-violet-400"
                        : "bg-transparent border-[--mia-glass-border] text-[--mia-text-muted] hover:border-violet-500/20 hover:text-[--mia-text-secondary]"
                    )}
                    title="Mostrar raciocínio da IA"
                  >
                    <Brain className="h-3 w-3" />
                    Reasoning
                  </button>
                )}

                {rawMode && (
                  <span className="ml-auto text-[10px] text-[--mia-text-muted] whitespace-nowrap">
                    Chat livre
                  </span>
                )}
              </div>

              {/* Composer */}
              <MiaComposer
                value={input}
                onChange={setInput}
                onSend={handleSend}
                onStop={abortStream}
                isStreaming={isStreaming}
                disabled={false}
              />

              {/* Disclaimer */}
              <div className="mt-2 text-center pb-1">
                <span className="text-[10px] text-[--mia-text-muted]">A MIA pode cometer erros. Verifique informações importantes.</span>
              </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

