import { useState, useMemo } from 'react';
import { Search, MessageSquare, Trash2 } from 'lucide-react';
import { Input } from '@/shared/ui/input';
import { ScrollArea } from '@/shared/ui/scroll-area';
import { cn } from '@/shared/lib/utils';
import { isToday, isYesterday, isThisWeek, parseISO } from 'date-fns';
import { MiaConversation } from '@/shared/contexts/MiaContext';

interface MiaHistoryPopoverProps {
  conversations: MiaConversation[];
  activeId: string | null;
  onSelect: (id: string) => void;
  onDelete: (id: string) => void;
  onClose?: () => void;
}

export function MiaHistoryPopoverContent({
  conversations,
  activeId,
  onSelect,
  onDelete,
  onClose
}: MiaHistoryPopoverProps) {
  const [searchQuery, setSearchQuery] = useState('');

  const filteredConversations = useMemo(() => {
    if (!searchQuery.trim()) return conversations;
    return conversations.filter(c => 
      c.title?.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [conversations, searchQuery]);

  const groupedConversations = useMemo(() => {
    const groups: Record<string, MiaConversation[]> = {
      'Hoje': [],
      'Ontem': [],
      'Esta Semana': [],
      'Anteriores': []
    };

    filteredConversations.forEach(conv => {
      const date = parseISO(conv.updatedAt);
      if (isToday(date)) groups['Hoje'].push(conv);
      else if (isYesterday(date)) groups['Ontem'].push(conv);
      else if (isThisWeek(date)) groups['Esta Semana'].push(conv);
      else groups['Anteriores'].push(conv);
    });

    return groups;
  }, [filteredConversations]);

  return (
    <div className="flex flex-col h-full bg-[--mia-bg-subtle]">
      {/* Search */}
      <div className="px-3 py-3 border-b border-[--mia-glass-border]/50">
        <div className="relative group">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-[--mia-text-muted] group-focus-within:text-[--mia-accent] transition-colors" />
          <Input data-mia-field="search_query" 
            placeholder="Buscar conversas..." 
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-9 h-9 rounded-xl bg-[--mia-bg-elevated] border-[--mia-glass-border] focus-visible:ring-[--mia-accent]/20"
          />
        </div>
      </div>

      {/* List */}
      <ScrollArea className="flex-1 max-h-[400px]">
        <div className="px-2 pb-4">
          {Object.entries(groupedConversations).map(([group, items]) => (
            items.length > 0 && (
              <div key={group} className="mt-3 first:mt-2">
                <h3 className="text-[10px] uppercase tracking-wider text-[--mia-text-muted] font-semibold px-3 py-1.5">
                  {group}
                </h3>
                <div className="space-y-0.5">
                  {items.map((conv) => (
                    <div
                      key={conv.id}
                      onClick={() => {
                        onSelect(conv.id);
                        onClose?.();
                      }}
                      className={cn(
                        "group relative flex items-center gap-2.5 px-3 py-2 rounded-xl cursor-pointer transition-all duration-200",
                        activeId === conv.id
                          ? "bg-[--mia-accent-subtle] text-[--mia-text-primary]"
                          : "hover:bg-[--mia-bg-elevated] text-[--mia-text-secondary] hover:text-[--mia-text-primary]"
                      )}
                    >
                      <MessageSquare className={cn(
                        "h-3.5 w-3.5 shrink-0 transition-colors",
                        activeId === conv.id ? "text-[--mia-accent]" : "text-[--mia-text-muted] group-hover:text-[--mia-text-secondary]"
                      )} />
                      <span className="flex-1 text-[13px] font-medium truncate">
                        {conv.title || 'Nova Conversa'}
                      </span>
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          if(confirm("Deseja deletar esta conversa?")) {
                             onDelete(conv.id);
                          }
                        }}
                        className="opacity-0 group-hover:opacity-100 p-1 rounded-md hover:bg-destructive/10 hover:text-destructive transition-all duration-200"
                      >
                        <Trash2 className="h-3 w-3" />
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )
          ))}

          {filteredConversations.length === 0 && searchQuery && (
            <div className="px-3 py-8 text-center">
              <p className="text-sm text-[--mia-text-muted]">Nenhuma conversa encontrada</p>
            </div>
          )}
          {filteredConversations.length === 0 && !searchQuery && (
            <div className="px-3 py-8 text-center flex flex-col items-center">
               <MessageSquare className="h-8 w-8 text-[--mia-text-muted]/40 mb-2" />
               <p className="text-sm text-[--mia-text-muted]">Nenhuma conversa</p>
            </div>
          )}
        </div>
      </ScrollArea>
    </div>
  );
}

