// MIA Telemetry Root — component invisível que ativa captura global.
//
// Plug no App.tsx dentro do MiaProvider, antes das Routes. Não renderiza nada;
// só monta o hook que delega events do DOM pra mia_user_telemetry.
//
// ⚠️ DESIGN INVIOLÁVEL — captura SEMPRE, INDEPENDENTE de MIA mode.
//
// O sistema captura uso de TODOS os usuários TODO o tempo, mesmo quando
// MIA glass-box agent está DESLIGADO. O `mia_active` no row é apenas um
// FLAG INFORMATIVO indicando o estado no momento — útil pra comparar
// adoção "com MIA vs sem MIA" no pattern detector — mas NÃO controla
// se telemetria roda.
//
// Captura NÃO depende de:
//  - localStorage.mia_glassbox_mode === '1' (essa flag é APENAS pro agent)
//  - User clicar/abrir o painel MIA
//  - User ter alguma permissão específica
//
// Captura depende SOMENTE de:
//  - User estar logado (auth.uid() não-null pra inserir via RLS)
//  - App.tsx montar MiaProvider (o que acontece em toda rota autenticada)

import { useEffect } from 'react';
import { useTelemetryAutoCapture } from '../hooks/useTelemetryAutoCapture';
import { setupTelemetry } from '../lib/telemetry';

export function MiaTelemetryRoot(): null {
  // Setup unload listeners (1x). Roda SEMPRE — não checa MIA mode.
  useEffect(() => {
    const cleanup = setupTelemetry();
    return cleanup;
  }, []);

  // Auto-capture routes/clicks/forms — SEMPRE ativo (vide design acima)
  useTelemetryAutoCapture();

  return null;
}

