export function useTelemetryAutoCapture(): void {
  const location = useLocation();
  const { selectedStore } = useStore();
  const { user } = useAuth();
  const { isAdmin } = usePermissions();

  // ─── Context update ────────────────────────────────────────
  useEffect(() => {
    setTelemetryContext({
      store_id: selectedStore?.id,
      loja_nome: selectedStore?.shortName,
      user_role: deriveUserRole(user) ?? (isAdmin() ? 'admin' : undefined),
      mia_active: typeof window !== 'undefined' && localStorage.getItem('mia_glassbox_mode') === '1',
    });
  }, [selectedStore, user, isAdmin]);

  // ─── Route tracking (enter + dwell) ───────────────────────
  const routeStartRef = useRef<{ path: string; ts: number } | null>(null);
  useEffect(() => {
    const now = Date.now();
    if (routeStartRef.current) {
      const dwell = now - routeStartRef.current.ts;
      if (dwell > 500) {
        track('route_dwell', {
          route: routeStartRef.current.path,
          dwell_ms: dwell,
        });
      }
    }
    routeStartRef.current = { path: location.pathname, ts: now };
    track('route_enter', { route: location.pathname });
  }, [location.pathname]);

  // ─── Click delegation ──────────────────────────────────────
  // Captura: selector, label, modifier keys, coordenadas + quadrante do
  // viewport. Coords permitem heatmap visual ("onde o user clica mais").
  useEffect(() => {
    const handler = (e: MouseEvent) => {
      const target = e.target as HTMLElement | null;
      if (!target) return;
      const info = findClickTarget(target);
      if (!info || (!info.selector && !info.label)) return;
      const modifiers: string[] = [];
      if (e.ctrlKey) modifiers.push('ctrl');
      if (e.shiftKey) modifiers.push('shift');
      if (e.altKey) modifiers.push('alt');
      if (e.metaKey) modifiers.push('meta');

      // Coordenadas relativas ao viewport (0-1 pra normalizar entre devices)
      const x = e.clientX;
      const y = e.clientY;
      const vw = window.innerWidth;
      const vh = window.innerHeight;
      const xNorm = vw > 0 ? +(x / vw).toFixed(3) : 0;
      const yNorm = vh > 0 ? +(y / vh).toFixed(3) : 0;

      // Quadrante (TL/TR/BL/BR/center) — útil pra GROUP BY em heatmap rápido
      const isCenter = xNorm > 0.33 && xNorm < 0.67 && yNorm > 0.33 && yNorm < 0.67;
      const quadrant = isCenter ? 'center'
        : xNorm < 0.5
          ? (yNorm < 0.5 ? 'TL' : 'BL')
          : (yNorm < 0.5 ? 'TR' : 'BR');

      track('click', {
        selector: info.selector,
        label: info.label,
        metadata: {
          role: info.role,
          x,
          y,
          x_norm: xNorm,
          y_norm: yNorm,
          quadrant,
          ...(modifiers.length > 0 ? { modifiers } : {}),
        },
      });
    };
    document.addEventListener('click', handler, { passive: true, capture: true });
    return () => document.removeEventListener('click', handler, { capture: true });
  }, []);

