import { SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2'

// ============================================================================
// LOGISTICS TOOLS — 100% RPCs mia_* (padrão Finance)
// SQL pré-testado, campos otimizados, limit clauses, error hints
// ============================================================================

// ── Date resolver — converts relative dates to YYYY-MM-DD (Brazil timezone) ──
// LLMs can't do date arithmetic. This runs server-side, zero LLM calculation.
function resolveDate(input: string | null | undefined): string | null {
    if (!input) return null
    // Already YYYY-MM-DD
    if (/^\d{4}-\d{2}-\d{2}$/.test(input)) return input

    const now = new Date()
    const br = new Date(now.toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }))
    const today = new Date(br.getFullYear(), br.getMonth(), br.getDate())

    const key = input.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim()

    // Direct keywords
    if (key === 'hoje' || key === 'today') return fmt(today)
    if (key === 'amanha' || key === 'tomorrow') return fmt(addDays(today, 1))
    if (key === 'ontem' || key === 'yesterday') return fmt(addDays(today, -1))

    // Day of week → next occurrence (0=Sun, 1=Mon, ... 6=Sat)
    const dayMap: Record<string, number> = {
        'domingo': 0, 'dom': 0, 'sunday': 0,
        'segunda': 1, 'seg': 1, 'monday': 1,
        'terca': 2, 'ter': 2, 'tuesday': 2,
        'quarta': 3, 'qua': 3, 'wednesday': 3,
        'quinta': 4, 'qui': 4, 'thursday': 4,
        'sexta': 5, 'sex': 5, 'friday': 5,
        'sabado': 6, 'sab': 6, 'saturday': 6,
    }

    if (dayMap[key] !== undefined) {
        const target = dayMap[key]
        const current = today.getDay()
        let diff = target - current
        if (diff <= 0) diff += 7 // next occurrence
        return fmt(addDays(today, diff))
    }

    // Fallback: return as-is (let RPC handle or error)
    return input
}

function addDays(d: Date, n: number): Date {
    const r = new Date(d)
    r.setDate(r.getDate() + n)
    return r
}

function fmt(d: Date): string {
    return d.toISOString().split('T')[0]
}

export const logisticsToolsDefinition = [
    {
        name: "mia_encomendas",
        description: `LISTA DE ENCOMENDAS (cada linha = 1 encomenda) — tool padrão para qualquer pergunta sobre encomendas de um dia/período.
DECISÃO:
- "quantas encomendas hoje?" / "encomendas de hoje" / "encomendas da semana" → USE ESTE TOOL (não o _resumo). Depois responda: "Hoje temos N encomendas:\\n\\n<tabela resumida>". A contagem vem de length, a tabela vem dos dados retornados.
- Detalhes de um cliente, pedidos específicos, horários → ESTE TOOL.
- SÓ use mia_encomendas_resumo quando a pergunta for puramente analítica agregada ("total do mês", "média por dia", "crescimento vs mês passado") — NÃO para "quantas hoje".
- Para buscar apenas sem valor cadastrado → mia_encomendas_sem_valor.

Filtros: tipo, status, cliente, data única OU range (start_date+end_date), loja, preparador, lançador.
Exemplos: "deliveries de hoje", "encomendas da Giovanna", "retiradas prontas", "PJ da semana", "todas encomendas de março", "retiradas entre 01/03 e 31/03".

REGRAS DE TIPO (ENFORCED no wrapper — não adianta ignorar):
- User diz "encomendas" / "pedidos" SEM mencionar tipo → wrapper remove PJ automaticamente. Você vê apenas delivery + retirada. NÃO mencione PJ na resposta.
- User diz "delivery" / "entrega" → passe tipo='delivery'.
- User diz "retirada" / "busca na loja" → passe tipo='retirada'.
- User diz "PJ" / "pessoa jurídica" / "corporativo" → passe tipo='pj'. Só assim o wrapper libera PJ.
- User diz "TODAS encomendas incluindo PJ" / "tudo" / "incluir PJ" → passe incluir_pj=true.

RANGE: para período use start_date + end_date (ex: mês inteiro). Para dia único use date. NUNCA iterar por dia.
LIMIT: default 100, max 1000. Sempre suba limit quando o user pedir "todas" / "lista completa" / mês.
ORDEM: ASC por data quando filtro de data/range; DESC (mais recentes primeiro) quando sem filtro.
Retorna: id, cliente, telefone, tipo, status, data/hora, pedido(200c), valor, pagamento, preparado_por, lancado_por, finalizado_por/at, preparado_at, endereço, loja.`,
        parameters: { type: "object", properties: {
            tipo: { type: "string", enum: ["delivery", "retirada", "pj"], description: "delivery=entrega, retirada=busca na loja, pj=pessoa jurídica. Passe SOMENTE quando o user mencionar explicitamente o tipo." },
            status: { type: "string", enum: ["aberto", "pronto", "finalizado"] },
            client_name: { type: "string", description: "Nome do cliente (busca parcial)" },
            date: { type: "string", description: "Dia único YYYY-MM-DD ou relativo (hoje, amanha, ontem, segunda..domingo). NÃO usar junto com start_date/end_date." },
            start_date: { type: "string", description: "Data inicial do range YYYY-MM-DD. Usar com end_date para mês/semana inteiros." },
            end_date: { type: "string", description: "Data final do range YYYY-MM-DD. Usar com start_date." },
            loja_id: { type: "number", description: "ID da loja (1-6)" },
            preparado_por: { type: "string", description: "Nome de quem preparou (busca parcial)" },
            lancado_por: { type: "string", description: "Nome de quem lançou (busca parcial). Ex: 'ASHELLEY', 'JOAO'." },
            limit: { type: "number", description: "Max resultados. Default 100. Max 1000. Suba para mês inteiro." },
            incluir_pj: { type: "boolean", description: "true = incluir encomendas PJ. Default false. Use APENAS quando o user pedir 'todas incluindo PJ' ou 'tudo'." }
        }}
    },
    {
        name: "mia_eventos",
        description: `Buscar eventos da timeline: inaugurações, degustações, parcerias PJ.
Use quando: "eventos de abril", "próximos eventos", "eventos da Asa Sul", "eventos semana que vem".
NÃO use para: encomendas (use mia_encomendas), requisições (use mia_requisicoes).
Retorna: id, nome, data, hora, status, responsável, telefone, endereço, faturamento, loja. 22 eventos total.`,
        parameters: { type: "object", properties: {
            status: { type: "string", description: "Status do evento" },
            start_date: { type: "string", description: "Data início YYYY-MM-DD" },
            end_date: { type: "string", description: "Data fim YYYY-MM-DD" },
            loja_id: { type: "number", description: "ID da loja (1-6)" },
            limit: { type: "number", description: "Max resultados. Default 20." }
        }}
    },
    {
        name: "mia_requisicoes",
        description: `Buscar requisições inter-loja com filtros e contagem de itens.
Use quando: "requisições pendentes", "o que está em separação?", "requisições da Asa Sul", "requisições da semana".
NÃO use para: itens de UMA requisição (use mia_requisicao_itens), resumo com alertas (use mia_requisicoes_resumo).
Fluxo: em_fila → em_progresso → finalizada. 329 requisições total.
Retorna: id, nome, status, loja_solicitante, loja_preparadora, datas, horas_idade, total_itens. Max 20.`,
