// ============================================================================
// IMPLEMENTATIONS — todas chamam RPCs Supabase (SQL pré-testado)
// ============================================================================

export const logisticsTools = {
    mia_encomendas: async (supabase: SupabaseClient, args: any) => {
        const { data, error } = await supabase.rpc('mia_encomendas', {
            p_tipo: args.tipo || null,
            p_status: args.status || null,
            p_client_name: args.client_name || null,
            p_date: resolveDate(args.date),
            p_loja_id: args.loja_id || null,
            p_preparado_por: args.preparado_por || null,
            p_limit: args.limit || 100,
            p_start_date: resolveDate(args.start_date),
            p_end_date: resolveDate(args.end_date),
            p_lancado_por: args.lancado_por || null
        })
        if (error) return JSON.stringify({ error: error.message })

        // ENFORCED: remove PJ quando user não pediu explicitamente
        // (tipo='pj' OU incluir_pj=true → libera PJ; caso contrário filtra)
        const userPediuPj = args.tipo === 'pj' || args.incluir_pj === true
        if (!userPediuPj && Array.isArray(data)) {
            const filtered = data.filter((e: any) => e?.tipo !== 'pj')
            const removidos = data.length - filtered.length
            if (removidos > 0) {
                return JSON.stringify({
                    encomendas: filtered,
                    _nota: `${removidos} encomenda(s) PJ ocultada(s). Não mencione PJ na resposta. Se o user quiser PJ, pedir explicitamente.`
                })
            }
            return JSON.stringify(filtered)
        }
        return JSON.stringify(data)
    },

    mia_eventos: async (supabase: SupabaseClient, args: any) => {
        const { data, error } = await supabase.rpc('mia_eventos', {
            p_status: args.status || null,
            p_start_date: resolveDate(args.start_date),
            p_end_date: resolveDate(args.end_date),
            p_loja_id: args.loja_id || null,
            p_limit: args.limit || 20
        })
        if (error) return JSON.stringify({ error: error.message })
        return JSON.stringify(data)
    },

    mia_requisicoes: async (supabase: SupabaseClient, args: any) => {
        const { data, error } = await supabase.rpc('mia_requisicoes', {
            p_status: args.status || null,
            p_loja_solicitante: args.loja_solicitante || null,
            p_loja_preparadora: args.loja_preparadora || null,
            p_start_date: resolveDate(args.start_date),
            p_end_date: resolveDate(args.end_date),
            p_limit: args.limit || 20
        })
        if (error) return JSON.stringify({ error: error.message })
        return JSON.stringify(data)
    },

    mia_requisicao_itens: async (supabase: SupabaseClient, args: any) => {
        const { data, error } = await supabase.rpc('mia_requisicao_itens', {
            p_requisicao_id: args.requisicao_id
        })
        if (error) return JSON.stringify({ error: error.message })
        return JSON.stringify(data)
    },

    mia_requisicoes_resumo: async (supabase: SupabaseClient, args: any) => {
        const { data, error } = await supabase.rpc('mia_requisicoes_resumo', {
            p_loja_id: args.loja_id || null
        })
        if (error) return JSON.stringify({ error: error.message })
        return JSON.stringify(data)
    },

    mia_encomendas_resumo: async (supabase: SupabaseClient, args: any) => {
        const { data, error } = await supabase.rpc('mia_encomendas_resumo', {
            p_date: resolveDate(args.date),
            p_loja_id: args.loja_id || null,
            p_start_date: resolveDate(args.start_date),
            p_end_date: resolveDate(args.end_date)
        })
        if (error) return JSON.stringify({ error: error.message })

        // ENFORCED: remove PJ do breakdown quando user não pediu
        if (args.incluir_pj !== true && data) {
            try {
                const result: any = Array.isArray(data) ? (data[0] ? { ...data[0] } : null) : { ...data }
                if (result && typeof result === 'object') {
                    const pjCount = Number(result?.por_tipo?.pj) || 0
                    // Remove campo pj do breakdown
                    if (result.por_tipo && typeof result.por_tipo === 'object') {
                        const { pj: _ignored, ...semPj } = result.por_tipo
                        result.por_tipo = semPj
                    }
                    // Ajusta total subtraindo PJ
                    if (typeof result.total === 'number' && pjCount > 0) {
                        result.total = Math.max(0, result.total - pjCount)
                    }
                    // Filtra listas de encomendas (proximas/recentes/etc) se vierem
                    for (const key of ['proximas', 'recentes', 'encomendas', 'lista']) {
                        if (Array.isArray(result[key])) {
                            result[key] = result[key].filter((e: any) => e?.tipo !== 'pj')
                        }
                    }
                    if (pjCount > 0) {
                        result._nota = `${pjCount} encomenda(s) PJ ocultada(s) do breakdown. NÃO mencione PJ na resposta. Se user quiser PJ, pedir explicitamente.`
                    }
                    return JSON.stringify(result)
                }
            } catch (filterErr) {
                console.warn('[mia_encomendas_resumo] PJ filter failed:', filterErr)
            }
        }
        return JSON.stringify(data)
    },

    mia_itens_enviados_resumo: async (supabase: SupabaseClient, args: any) => {
        const { data, error } = await supabase.rpc('mia_itens_enviados_resumo', {
            p_product_name: args.product_name || null,
            p_start_date: resolveDate(args.start_date),
            p_end_date: resolveDate(args.end_date),
            p_loja_solicitante: args.loja_solicitante || null,
            p_limit: args.limit || 20
        })
        if (error) return JSON.stringify({ error: error.message })
        return JSON.stringify(data)
    },

    mia_requisicoes_por_dia: async (supabase: SupabaseClient, args: any) => {
        const { data, error } = await supabase.rpc('mia_requisicoes_por_dia', {
            p_start_date: resolveDate(args.start_date),
            p_end_date: resolveDate(args.end_date),
            p_limit: args.limit || 14
        })
        if (error) return JSON.stringify({ error: error.message })
        return JSON.stringify(data)
    },

    mia_editar_encomenda: async (supabase: SupabaseClient, args: any) => {
        const isPreview = args.preview === true
        // Anti-loop: detecta preview duplicado em <90s pro mesmo id+campos
        // (mesmo padrão de mia_finalizar_requisicoes)
        const { getMiaSessionContext } = await import('./finance_tools.ts')
        const ctx = getMiaSessionContext()
        const sessionId = ctx.session_id || 'unknown'
        const { preview: _p, ...mainArgs } = args || {}
        const cacheKey = `${sessionId}:mia_editar_encomenda:${JSON.stringify(mainArgs)}`
        ;(globalThis as any).__miaPreviewCache = (globalThis as any).__miaPreviewCache || new Map<string, number>()
        const cache = (globalThis as any).__miaPreviewCache as Map<string, number>
        if (isPreview) {
            const previousTs = cache.get(cacheKey)
            const now = Date.now()
            cache.set(cacheKey, now)
            if (previousTs && now - previousTs < 90_000) {
                return JSON.stringify({
                    anti_loop_detected: true,
                    error: 'PREVIEW_DUPLICADO',
                    message: 'Você JÁ chamou mia_editar_encomenda com preview=true há poucos segundos para esta mesma encomenda. Se o usuário confirmou com "sim", chame AGORA com preview=false (mesmos args). NÃO chame preview=true de novo — você está em loop.',
                    args_repetidos: mainArgs
                })
            }
        } else {
            cache.delete(cacheKey)
        }

        const { data, error } = await supabase.rpc('mia_editar_encomenda', {
            p_id: args.id,
            p_valor: args.valor || null,
            p_status: args.status || null,
            p_observacao: args.observacao || null,
            p_hora_entrega: args.hora_entrega || null,
            p_preview: isPreview
        })
        if (error) return JSON.stringify({ error: error.message })
        return JSON.stringify(data)
    },

    mia_encomendas_sem_valor: async (supabase: SupabaseClient, args: any) => {
        const { data, error } = await supabase.rpc('mia_encomendas_sem_valor', {
            p_limit: args.limit || 20
        })
        if (error) return JSON.stringify({ error: error.message })
        return JSON.stringify(data)
    },

    mia_finalizar_requisicoes: async (supabase: SupabaseClient, args: any) => {
        // Anti-loop: detecta preview duplicado em <90s pra mesmos args
        const { getMiaSessionContext } = await import('./finance_tools.ts')
        const ctx = getMiaSessionContext()
        const isPreview = args.preview !== false
        const sessionId = ctx.session_id || 'unknown'
        const { preview: _p, ...mainArgs } = args || {}
        const cacheKey = `${sessionId}:mia_finalizar_requisicoes:${JSON.stringify(mainArgs)}`
        // Usa Map global declarada em runtime do edge function
        ;(globalThis as any).__miaPreviewCache = (globalThis as any).__miaPreviewCache || new Map<string, number>()
        const cache = (globalThis as any).__miaPreviewCache as Map<string, number>
        if (isPreview) {
            const previousTs = cache.get(cacheKey)
            const now = Date.now()
            cache.set(cacheKey, now)
            if (previousTs && now - previousTs < 90_000) {
                return JSON.stringify({
                    anti_loop_detected: true,
                    error: 'PREVIEW_DUPLICADO',
                    message: 'Você JÁ chamou mia_finalizar_requisicoes com preview=true há poucos segundos. Se o user confirmou, chame AGORA com preview=false (mesmos args). Não chame preview=true de novo — você está em loop.',
                    args_repetidos: mainArgs
                })
            }
        } else {
            cache.delete(cacheKey)
        }

        const { data, error } = await supabase.rpc('mia_finalizar_requisicoes', {
            p_status_atual: args.status_atual || 'em_fila',
            p_loja_solicitante: args.loja_solicitante || null,
            p_loja_preparadora: args.loja_preparadora || null,
            p_data_inicio: args.data_inicio || null,
            p_data_fim: args.data_fim || null,
            p_preview: isPreview,
            p_user_id: ctx.user_id || null,
        })
        if (error) return JSON.stringify({ error: error.message })
        return JSON.stringify(data)
    },
}

